CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(  key, content, use_cases, content='memories', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS kb_fts USING fts5(  content, heading_path, content='kb_documents', content_rowid='id');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_chunks_fts USING fts5(  chunk_text, content='memory_chunks', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_units_fts USING fts5(  unit_key, unit_text, content='memory_units', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_negation_fts USING fts5(  negation_tokens, content='memories', content_rowid='id',  tokenize='unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS prospective_memories_fts USING fts5(  trigger_text, content='prospective_memories', content_rowid='id',  tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS epistemic_directives_fts USING fts5(  question, topic, content='epistemic_directives', content_rowid='id',  tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memories_code_fts USING fts5(key, content, content='memories', content_rowid='id', tokenize='trigram');
CREATE VIRTUAL TABLE IF NOT EXISTS code_fts USING fts5(content, content='file_contents', content_rowid='file_id', tokenize='unicode61');
CREATE TABLE IF NOT EXISTS rules (  id INTEGER PRIMARY KEY AUTOINCREMENT,  polarity TEXT NOT NULL,  title TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  weight INTEGER NOT NULL DEFAULT 5,  domain TEXT NOT NULL DEFAULT '',  directive_type TEXT NOT NULL DEFAULT 'soft',  expires_at TEXT DEFAULT NULL,  last_reinforced_at TEXT DEFAULT NULL,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL UNIQUE,  root TEXT NOT NULL,  workspace TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL,  trust TEXT NOT NULL DEFAULT 'trusted' CHECK (trust IN ('trusted', 'untrusted')), lifecycle_state TEXT NOT NULL DEFAULT 'current' CHECK (lifecycle_state IN ('current','detached')), current_generation INTEGER NOT NULL DEFAULT 1 CHECK (current_generation > 0));
CREATE INDEX IF NOT EXISTS idx_projects_lifecycle ON projects(lifecycle_state, name);
CREATE TABLE IF NOT EXISTS code_project_aliases (  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, alias TEXT NOT NULL UNIQUE, alias_kind TEXT NOT NULL DEFAULT 'checkout', is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IN (0,1)), first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_code_project_alias_project ON code_project_aliases(project_id, is_current);
CREATE TABLE IF NOT EXISTS code_project_generations (  id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, generation INTEGER NOT NULL CHECK (generation > 0), root TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'current' CHECK (state IN ('current','superseded','detached')), created_at TEXT NOT NULL, detached_at TEXT NOT NULL DEFAULT '', UNIQUE(project_id, generation));
CREATE INDEX IF NOT EXISTS idx_code_project_generation_state ON code_project_generations(project_id, state, generation);
CREATE TABLE IF NOT EXISTS files (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  path TEXT NOT NULL,  purpose TEXT NOT NULL DEFAULT '',  hash TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL,  language TEXT NOT NULL DEFAULT '',  vendored INTEGER NOT NULL DEFAULT 0,  UNIQUE(project_id, generation, path));
CREATE TABLE IF NOT EXISTS file_exports (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS file_imports (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '',  is_system INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS terms (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '',  def_kind TEXT NOT NULL DEFAULT '',  line INTEGER NOT NULL DEFAULT 0,  line_end INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stopwords (  word TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS entity_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source TEXT NOT NULL,  relation TEXT NOT NULL,  target TEXT NOT NULL,  weight INTEGER NOT NULL DEFAULT 1,  window_id INTEGER, utility_score REAL NOT NULL DEFAULT 0.0, valid_from TEXT NOT NULL DEFAULT '', valid_until TEXT NOT NULL DEFAULT '', relation_id INTEGER, subject_kind INTEGER, object_kind INTEGER,  utility_touched_at TEXT NOT NULL DEFAULT '',  structural_weight INTEGER NOT NULL DEFAULT 0,  edge_origin TEXT NOT NULL DEFAULT 'session',  projection_generation_id INTEGER NOT NULL DEFAULT 0,  structural_updated_at TEXT NOT NULL DEFAULT '',  edge_class TEXT NOT NULL DEFAULT 'cooccurrence',  confidence_class TEXT NOT NULL DEFAULT 'C' CHECK (confidence_class IN ('A', 'B', 'C')),  confidence REAL NOT NULL DEFAULT 0.4,  asserted_at TEXT NOT NULL DEFAULT '',  superseded_at TEXT NOT NULL DEFAULT '',  suppressed INTEGER NOT NULL DEFAULT 0, assertion_kind TEXT NOT NULL DEFAULT 'world_fact', lifecycle_state TEXT NOT NULL DEFAULT 'persistent', authority_rank INTEGER NOT NULL DEFAULT 0, actor_principal TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, prior_version_id INTEGER NOT NULL DEFAULT 0, commit_id TEXT NOT NULL DEFAULT '', invalidated_at TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_entity_edges_fact_lifecycle ON entity_edges(source,relation,lifecycle_state,authority_rank) WHERE edge_class='semantic';
CREATE INDEX IF NOT EXISTS idx_entity_edges_fact_commit ON entity_edges(commit_id) WHERE edge_class='semantic' AND commit_id<>'';
-- rel_types: typed-relationship ontology (typed-fact §1 / P1), live overlay of the in-code SEED_ONTOLOGY.
CREATE TABLE IF NOT EXISTS rel_types (  id INTEGER PRIMARY KEY AUTOINCREMENT,  rel_type TEXT NOT NULL UNIQUE,  head_kinds TEXT NOT NULL DEFAULT '',  tail_kinds TEXT NOT NULL DEFAULT '',  is_symmetric INTEGER NOT NULL DEFAULT 0,  inverse_rel_type TEXT NOT NULL DEFAULT '',  correction_behavior TEXT NOT NULL DEFAULT 'supersede',  category TEXT NOT NULL DEFAULT '',  sensitivity TEXT NOT NULL DEFAULT 'pii',  is_hierarchy_rel INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS fact_evidence ( id INTEGER PRIMARY KEY AUTOINCREMENT, assertion_id INTEGER NOT NULL REFERENCES entity_edges(id) ON DELETE CASCADE, source_kind TEXT NOT NULL DEFAULT 'observation', source_id TEXT NOT NULL, source_span TEXT NOT NULL DEFAULT '', evidence_hash TEXT NOT NULL DEFAULT '', actor_principal TEXT NOT NULL DEFAULT '', observed_at TEXT NOT NULL DEFAULT '', ingest_run_id TEXT NOT NULL DEFAULT '', commit_id TEXT NOT NULL DEFAULT '', invalidated_at TEXT NOT NULL DEFAULT '', stance TEXT NOT NULL DEFAULT 'supports' CHECK (stance IN ('supports','contradicts')), created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(assertion_id,source_kind,source_id,source_span,evidence_hash,stance));
CREATE INDEX IF NOT EXISTS idx_fact_evidence_assertion ON fact_evidence(assertion_id,id);
CREATE INDEX IF NOT EXISTS idx_fact_evidence_source ON fact_evidence(source_kind,source_id);
CREATE INDEX IF NOT EXISTS idx_fact_evidence_ingest ON fact_evidence(ingest_run_id,id);
CREATE TABLE IF NOT EXISTS memory_fact_actors ( memory_id INTEGER PRIMARY KEY REFERENCES memories(id) ON DELETE CASCADE, actor_principal TEXT NOT NULL, actor_role TEXT NOT NULL, authority_rank INTEGER NOT NULL, authenticated INTEGER NOT NULL DEFAULT 0, captured_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS fact_graph_commits ( commit_id TEXT PRIMARY KEY, parent_commit_id TEXT NOT NULL DEFAULT '', operation TEXT NOT NULL, actor_principal TEXT NOT NULL, actor_role TEXT NOT NULL, authority_rank INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'applied' CHECK (status IN ('open','applied','rolled_back','erased')), reversible INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')), rolled_back_at TEXT NOT NULL DEFAULT '', rolled_back_by TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS fact_graph_changes ( id INTEGER PRIMARY KEY AUTOINCREMENT, commit_id TEXT NOT NULL REFERENCES fact_graph_commits(commit_id) ON DELETE CASCADE, assertion_id INTEGER NOT NULL DEFAULT 0, object_kind TEXT NOT NULL DEFAULT 'assertion', object_key TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, existed_before INTEGER NOT NULL DEFAULT 0, existed_after INTEGER NOT NULL DEFAULT 0, before_lifecycle TEXT NOT NULL DEFAULT '', after_lifecycle TEXT NOT NULL DEFAULT '', before_superseded_at TEXT NOT NULL DEFAULT '', after_superseded_at TEXT NOT NULL DEFAULT '', before_invalidated_at TEXT NOT NULL DEFAULT '', after_invalidated_at TEXT NOT NULL DEFAULT '', before_suppressed INTEGER NOT NULL DEFAULT 0, after_suppressed INTEGER NOT NULL DEFAULT 0, before_confidence REAL NOT NULL DEFAULT 0, after_confidence REAL NOT NULL DEFAULT 0, before_authority_rank INTEGER NOT NULL DEFAULT 0, after_authority_rank INTEGER NOT NULL DEFAULT 0, before_version INTEGER NOT NULL DEFAULT 0, after_version INTEGER NOT NULL DEFAULT 0, diff_detail TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_fact_graph_changes_commit ON fact_graph_changes(commit_id,id);
CREATE INDEX IF NOT EXISTS idx_fact_graph_changes_assertion ON fact_graph_changes(assertion_id,id);
CREATE TABLE IF NOT EXISTS fact_review_actions ( id INTEGER PRIMARY KEY AUTOINCREMENT, assertion_id INTEGER NOT NULL REFERENCES entity_edges(id) ON DELETE CASCADE, action TEXT NOT NULL CHECK (action IN ('approve','reject','undo')), prior_lifecycle TEXT NOT NULL, new_lifecycle TEXT NOT NULL, actor_principal TEXT NOT NULL, commit_id TEXT NOT NULL REFERENCES fact_graph_commits(commit_id), reverses_review_id INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_fact_review_assertion ON fact_review_actions(assertion_id,id);
CREATE TABLE IF NOT EXISTS fact_erasure_reports ( commit_id TEXT PRIMARY KEY REFERENCES fact_graph_commits(commit_id), selector TEXT NOT NULL, assertion_count INTEGER NOT NULL DEFAULT 0, evidence_count INTEGER NOT NULL DEFAULT 0, residual_data TEXT NOT NULL DEFAULT '', completed_at TEXT NOT NULL DEFAULT '');
CREATE VIEW IF NOT EXISTS fact_assertions_current AS SELECT e.id,e.source,e.relation,e.target,e.subject_kind,e.object_kind,e.assertion_kind,e.lifecycle_state,e.confidence,e.authority_rank,e.valid_from,e.valid_until,e.asserted_at,e.actor_principal,e.version,e.prior_version_id,e.commit_id,(SELECT COUNT(*) FROM fact_evidence fe WHERE fe.assertion_id=e.id AND fe.stance='supports' AND fe.invalidated_at='') AS evidence_count FROM entity_edges e WHERE e.edge_class='semantic' AND e.lifecycle_state IN ('persistent','promoted') AND e.superseded_at='' AND e.invalidated_at='' AND e.suppressed=0;
CREATE VIEW IF NOT EXISTS entity_fact_profiles AS SELECT source AS entity,relation,target,assertion_kind,confidence,evidence_count,id AS assertion_id FROM fact_assertions_current;
CREATE VIEW IF NOT EXISTS entity_mental_models AS SELECT source AS entity,relation AS dimension,target AS inferred_value,COUNT(*) AS supporting_assertions,SUM(evidence_count) AS supporting_evidence,AVG(confidence) AS confidence,MIN(valid_from) AS valid_from,MAX(valid_until) AS valid_until FROM fact_assertions_current WHERE assertion_kind IN ('world_fact','experience','observation') GROUP BY source,relation,target;
CREATE TRIGGER IF NOT EXISTS entity_edges_semantic_guard_insert BEFORE INSERT ON entity_edges WHEN NEW.edge_class='semantic' AND (NEW.commit_id='' OR NOT EXISTS (SELECT 1 FROM fact_graph_commits WHERE commit_id=NEW.commit_id AND status='open')) BEGIN SELECT RAISE(ABORT,'semantic facts must be changed through fact_mutation'); END;
CREATE TRIGGER IF NOT EXISTS entity_edges_semantic_guard_update BEFORE UPDATE ON entity_edges WHEN (NEW.edge_class='semantic' OR OLD.edge_class='semantic') AND (NEW.commit_id='' OR NOT EXISTS (SELECT 1 FROM fact_graph_commits WHERE commit_id=NEW.commit_id AND status='open')) BEGIN SELECT RAISE(ABORT,'semantic facts must be changed through fact_mutation'); END;
CREATE TRIGGER IF NOT EXISTS entity_edges_semantic_guard_delete BEFORE DELETE ON entity_edges WHEN OLD.edge_class='semantic' AND NOT EXISTS (SELECT 1 FROM fact_graph_commits WHERE status='open' AND operation='fact.erase' AND reversible=0) BEGIN SELECT RAISE(ABORT,'semantic facts must be erased through fact_mutation'); END;
CREATE TRIGGER IF NOT EXISTS entity_edges_mental_model_guard_insert BEFORE INSERT ON entity_edges WHEN NEW.edge_class='semantic' AND NEW.assertion_kind='mental_model' BEGIN SELECT RAISE(ABORT,'mental models are derived views, not assertion rows'); END;
CREATE TRIGGER IF NOT EXISTS entity_edges_mental_model_guard_update BEFORE UPDATE ON entity_edges WHEN NEW.edge_class='semantic' AND NEW.assertion_kind='mental_model' BEGIN SELECT RAISE(ABORT,'mental models are derived views, not assertion rows'); END;
-- ontology_evaluations: self-extending ontology promotion pipeline (typed-fact §2 / P4).
CREATE TABLE IF NOT EXISTS ontology_evaluations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  rel_type TEXT NOT NULL UNIQUE,  occurrence_count INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'mapped', 'rejected')),  mapped_to TEXT NOT NULL DEFAULT '',  decided_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT '');
-- entity_registry / entity_aliases: surrogate-id entity canonicalization (typed-fact §3 / P2).
CREATE TABLE IF NOT EXISTS entity_registry (  canonical_id INTEGER PRIMARY KEY AUTOINCREMENT,  kind INTEGER NOT NULL DEFAULT 99,  status TEXT NOT NULL DEFAULT 'active',  merged_into INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_aliases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL DEFAULT '',  name_norm TEXT NOT NULL UNIQUE,  canonical_id INTEGER NOT NULL,  is_preferred INTEGER NOT NULL DEFAULT 0,  suppressed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_entity_aliases_cid ON entity_aliases(canonical_id);
-- entity_merges / entity_name_conflicts: merge audit (for unmerge) + ambiguity queue (typed-fact §3 / P2b).
CREATE TABLE IF NOT EXISTS entity_merges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  from_id INTEGER NOT NULL,  into_id INTEGER NOT NULL,  undone INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_name_conflicts (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name_norm TEXT NOT NULL UNIQUE,  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'failed')),  priority INTEGER NOT NULL DEFAULT 1,  retries INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS memories (  id INTEGER PRIMARY KEY AUTOINCREMENT,  tier TEXT NOT NULL DEFAULT 'L0',  kind TEXT NOT NULL DEFAULT 'fact',  key TEXT NOT NULL,  content TEXT NOT NULL DEFAULT '',  use_cases TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  use_count INTEGER NOT NULL DEFAULT 0,  last_used_at TEXT,  source_session TEXT,  valid_from TEXT,  valid_until TEXT,  artifact_type TEXT,  artifact_ref TEXT,  artifact_hash TEXT,  effectiveness REAL DEFAULT NULL,  sensitivity TEXT NOT NULL DEFAULT 'normal',  evidence_strength REAL NOT NULL DEFAULT 0.5,  observation_count INTEGER NOT NULL DEFAULT 1,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')), salience REAL NOT NULL DEFAULT 0.5, surprise REAL NOT NULL DEFAULT 0.5, contradiction_group TEXT NOT NULL DEFAULT '', merged_into INTEGER NOT NULL DEFAULT 0, negation_tokens TEXT NOT NULL DEFAULT '', lifecycle_state TEXT NOT NULL DEFAULT 'active', archive_reason TEXT NOT NULL DEFAULT '', ttl_at TEXT NOT NULL DEFAULT '', cognified_memory_kind TEXT NOT NULL DEFAULT '', provenance_category TEXT NOT NULL DEFAULT 'user_stated');
CREATE TABLE IF NOT EXISTS memory_provenance (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL,  action TEXT NOT NULL,  details TEXT,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_conflicts (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_a INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  memory_b INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  detected_at TEXT NOT NULL,  resolved INTEGER NOT NULL DEFAULT 0,  resolution TEXT);
CREATE TABLE IF NOT EXISTS tasks (  id INTEGER PRIMARY KEY AUTOINCREMENT,  parent_id INTEGER DEFAULT 0,  title TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'todo',  confidence REAL NOT NULL DEFAULT 1.0,  session_id TEXT,  success_criteria TEXT DEFAULT '',  description TEXT DEFAULT '',  acceptance_json TEXT DEFAULT '',  assignee TEXT DEFAULT '',  estimate_minutes INTEGER DEFAULT 0,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  target_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'depends_on');
CREATE TABLE IF NOT EXISTS decision_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  task_id INTEGER DEFAULT 0,  options TEXT NOT NULL,  chosen TEXT NOT NULL,  rationale TEXT NOT NULL DEFAULT '',  assumptions TEXT NOT NULL DEFAULT '',  outcome TEXT,  created_at TEXT NOT NULL,  status TEXT NOT NULL DEFAULT 'active',  revisit_when TEXT NOT NULL DEFAULT '',  supersedes_id INTEGER NOT NULL DEFAULT 0,  subject TEXT NOT NULL DEFAULT '',  author TEXT NOT NULL DEFAULT '',  linked_policy_id INTEGER NOT NULL DEFAULT 0);
-- kb_audit_event (S5 WORM store) — SQLite test-shim mirror of the Postgres table.
CREATE TABLE IF NOT EXISTS kb_audit_event (  seq INTEGER PRIMARY KEY,  ts TEXT NOT NULL,  actor_role TEXT NOT NULL DEFAULT '',  actor_principal TEXT NOT NULL DEFAULT '',  action TEXT NOT NULL,  subject TEXT NOT NULL DEFAULT '',  verdict TEXT NOT NULL DEFAULT '',  detail TEXT NOT NULL DEFAULT '',  key_id TEXT NOT NULL DEFAULT '',  prev_hash TEXT NOT NULL,  row_hash TEXT NOT NULL,  actor_issuer TEXT NOT NULL DEFAULT '',  actor_subject TEXT NOT NULL DEFAULT '',  transport_cn TEXT NOT NULL DEFAULT '',  team_id INTEGER NOT NULL DEFAULT 0,  selected_default_from TEXT NOT NULL DEFAULT '');
CREATE TRIGGER IF NOT EXISTS kb_audit_no_update BEFORE UPDATE ON kb_audit_event BEGIN SELECT RAISE(ABORT, 'WORM: kb_audit_event is append-only'); END;
CREATE TRIGGER IF NOT EXISTS kb_audit_no_delete BEFORE DELETE ON kb_audit_event BEGIN SELECT RAISE(ABORT, 'WORM: kb_audit_event is append-only'); END;
CREATE TABLE IF NOT EXISTS anti_patterns (  id INTEGER PRIMARY KEY AUTOINCREMENT,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  hit_count INTEGER NOT NULL DEFAULT 0,  confidence REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS kb_enrollments (  id INTEGER PRIMARY KEY AUTOINCREMENT,  scope TEXT NOT NULL DEFAULT '',  fingerprint TEXT NOT NULL,  serial TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'active',  issued_at TEXT NOT NULL DEFAULT '',  last_seen_at TEXT NOT NULL DEFAULT '',  expires_at TEXT NOT NULL DEFAULT '',  revoked_at TEXT NOT NULL DEFAULT '',  legacy INTEGER NOT NULL DEFAULT 0,  cert_issuer TEXT NOT NULL DEFAULT '',  cert_serial_norm TEXT NOT NULL DEFAULT '', authority_id TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_kbenroll_fp ON kb_enrollments(fingerprint);
CREATE INDEX IF NOT EXISTS idx_kbenroll_scope ON kb_enrollments(scope);
CREATE INDEX IF NOT EXISTS idx_kbenroll_authority ON kb_enrollments(authority_id);
-- P1 tenancy tables — SQLite shim mirror (plain tables only; RLS/roles/functions
-- are Postgres-only. Tenant-scoped db2 entrypoints hard-fail on the shim via the
-- C guard db2_tenant_require_pg(), so the shim never enforces tenancy — these
-- mirrors exist only so schema application and non-tenant reads do not error.)
CREATE TABLE IF NOT EXISTS kb_team (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL UNIQUE,  created_at TEXT NOT NULL DEFAULT '',  operator_id TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_project (  id INTEGER PRIMARY KEY AUTOINCREMENT,  parent INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  name TEXT NOT NULL,  access_mode TEXT NOT NULL DEFAULT 'team-open',  created_at TEXT NOT NULL DEFAULT '',  operator_id TEXT NOT NULL DEFAULT '',  UNIQUE(parent, name));
CREATE TABLE IF NOT EXISTS kb_team_membership (  id INTEGER PRIMARY KEY AUTOINCREMENT,  identity_key TEXT NOT NULL,  team INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  is_default INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '',  UNIQUE(identity_key, team));
CREATE UNIQUE INDEX IF NOT EXISTS idx_kbmember_default ON kb_team_membership(identity_key) WHERE is_default = 1;
CREATE TABLE IF NOT EXISTS kb_project_membership (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project INTEGER NOT NULL REFERENCES kb_project(id) ON DELETE CASCADE,  identity_key TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, identity_key));
CREATE TABLE IF NOT EXISTS kb_admin_grant (  id INTEGER PRIMARY KEY AUTOINCREMENT,  identity_key TEXT NOT NULL UNIQUE,  source TEXT NOT NULL DEFAULT '',  granted_at TEXT NOT NULL DEFAULT '',  granted_by TEXT NOT NULL DEFAULT '',  revoked_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_oidc_jwks (  id INTEGER PRIMARY KEY AUTOINCREMENT,  issuer TEXT NOT NULL,  kid TEXT NOT NULL,  jwk_json TEXT NOT NULL,  added_at TEXT NOT NULL DEFAULT '',  retired_at TEXT NOT NULL DEFAULT '',  UNIQUE(issuer, kid));
CREATE TABLE IF NOT EXISTS kb_console_oidc (  id INTEGER PRIMARY KEY,  issuer TEXT NOT NULL DEFAULT '',  audience TEXT NOT NULL DEFAULT '',  jwks_url TEXT NOT NULL DEFAULT '',  admin_claim TEXT NOT NULL DEFAULT '',  admin_values TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '');
-- P3a cost attribution (tiered-llm-p3a) — shim mirrors the DB2 tables ONLY; RLS,
-- WORM triggers, and the SECURITY DEFINER pricing/ledger functions CANNOT exist on
-- SQLite, so every P3a runtime path is gated by db2_tenant_require_pg() and hard-fails
-- on the shim. These CREATE TABLEs exist purely so a shim DB opens cleanly.
CREATE TABLE IF NOT EXISTS org_model_pricing (  id INTEGER PRIMARY KEY AUTOINCREMENT,  provider TEXT NOT NULL DEFAULT '',  billable_model TEXT NOT NULL,  version INTEGER NOT NULL,  input_usd_per_mtok TEXT NOT NULL,  output_usd_per_mtok TEXT NOT NULL,  cache_read_usd_per_mtok TEXT NOT NULL DEFAULT '0',  cache_write_usd_per_mtok TEXT NOT NULL DEFAULT '0',  effective_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT '',  UNIQUE(billable_model, version));
CREATE TABLE IF NOT EXISTS org_model_pricing_current (  billable_model TEXT PRIMARY KEY,  version INTEGER NOT NULL,  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_team_lead (  id INTEGER PRIMARY KEY AUTOINCREMENT,  identity_key TEXT NOT NULL,  team INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  granted_at TEXT NOT NULL DEFAULT '',  granted_by TEXT NOT NULL DEFAULT '',  revoked_at TEXT NOT NULL DEFAULT '',  UNIQUE(identity_key, team));
CREATE TABLE IF NOT EXISTS org_token_audit (  id INTEGER PRIMARY KEY AUTOINCREMENT,  request_id TEXT NOT NULL,  origin_cert_cn TEXT NOT NULL,  actor_issuer TEXT NOT NULL DEFAULT '',  actor_subject TEXT NOT NULL DEFAULT '',  team_id INTEGER NOT NULL REFERENCES kb_team(id),  project_id INTEGER REFERENCES kb_project(id),  billable_model TEXT NOT NULL,  served_model TEXT NOT NULL DEFAULT '',  pricing_version INTEGER NOT NULL,  prompt_tokens INTEGER NOT NULL DEFAULT 0,  completion_tokens INTEGER NOT NULL DEFAULT 0,  cache_read_tokens INTEGER NOT NULL DEFAULT 0,  cache_write_tokens INTEGER NOT NULL DEFAULT 0,  estimated_cost_usd TEXT NOT NULL DEFAULT '0',  state TEXT NOT NULL DEFAULT 'started',  session_id TEXT NOT NULL DEFAULT '',  delegation_id TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT '',  settled_at TEXT NOT NULL DEFAULT '',  UNIQUE(origin_cert_cn, request_id));
CREATE TABLE IF NOT EXISTS org_spend_rollup (  id INTEGER PRIMARY KEY AUTOINCREMENT,  team_id INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  project_id INTEGER REFERENCES kb_project(id) ON DELETE CASCADE,  billable_model TEXT NOT NULL,  day TEXT NOT NULL,  prompt_tokens INTEGER NOT NULL DEFAULT 0,  completion_tokens INTEGER NOT NULL DEFAULT 0,  cache_read_tokens INTEGER NOT NULL DEFAULT 0,  cache_write_tokens INTEGER NOT NULL DEFAULT 0,  cost_usd TEXT NOT NULL DEFAULT '0',  row_count INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS workflow_patterns (  id INTEGER PRIMARY KEY AUTOINCREMENT,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tool_registry (  name TEXT PRIMARY KEY,  description TEXT NOT NULL,  input_schema TEXT NOT NULL,  output_schema TEXT DEFAULT '',  side_effect TEXT NOT NULL DEFAULT 'read',  idempotent INTEGER NOT NULL DEFAULT 0,  enabled INTEGER NOT NULL DEFAULT 1,  tool_prompt TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS memory_health (  id INTEGER PRIMARY KEY AUTOINCREMENT,  cycle_at TEXT NOT NULL DEFAULT (datetime('now')),  total_memories INTEGER NOT NULL DEFAULT 0,  contradictions_detected INTEGER NOT NULL DEFAULT 0,  promotions INTEGER NOT NULL DEFAULT 0,  demotions INTEGER NOT NULL DEFAULT 0,  expirations INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS contradiction_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  detected_at TEXT NOT NULL DEFAULT (datetime('now')),  memory_a_id INTEGER REFERENCES memories(id) ON DELETE CASCADE,  memory_b_id INTEGER REFERENCES memories(id) ON DELETE CASCADE,  resolution TEXT NOT NULL DEFAULT 'pending',  details TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_workspaces (  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  workspace TEXT NOT NULL,  PRIMARY KEY(memory_id, workspace));
CREATE TABLE IF NOT EXISTS kind_lifecycle (  kind TEXT PRIMARY KEY,  promote_use_count INTEGER NOT NULL,  promote_confidence REAL NOT NULL,  demote_days INTEGER NOT NULL,  demote_confidence REAL NOT NULL,  expire_days INTEGER NOT NULL,  demotion_resistance REAL NOT NULL);
-- agent_outcomes was declared with (session_id, outcome, details, created_at) but
-- agent_runtime.c:record_outcome inserts (agent_name, role, outcome, reason, turns_used,
-- tools_called, tokens_used, tool_error_pattern, ...).  Every agent call logged
-- "no column named agent_name" and dropped the outcome row on the floor.  Drop
-- the stale table (log-only data, no FK deps) and recreate with the columns the
-- code actually writes and agent_eval.c reads.
DROP TABLE IF EXISTS agent_outcomes;
CREATE TABLE IF NOT EXISTS agent_outcomes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  agent_name TEXT NOT NULL DEFAULT '',  role TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL,  reason TEXT DEFAULT '',  turns_used INTEGER NOT NULL DEFAULT 0,  tools_called INTEGER NOT NULL DEFAULT 0,  tokens_used INTEGER NOT NULL DEFAULT 0,  tool_error_pattern TEXT DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_links (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'related',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS trace_mining_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  last_trace_id INTEGER NOT NULL DEFAULT 0,  mined_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS mining_jobs (  id TEXT PRIMARY KEY,  last_run_at TEXT,  hwm INTEGER NOT NULL DEFAULT 0,  interval_s INTEGER NOT NULL DEFAULT 300,  enabled INTEGER NOT NULL DEFAULT 1,  last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS interaction_event_embeddings (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_event_id INTEGER NOT NULL UNIQUE,  session_id TEXT NOT NULL DEFAULT '',  event_type TEXT NOT NULL,  role TEXT NOT NULL DEFAULT '',  failure_mode TEXT NOT NULL DEFAULT '', scope_kind TEXT NOT NULL DEFAULT 'workspace', scope_id TEXT NOT NULL DEFAULT '', task_family TEXT NOT NULL DEFAULT '', action_sequence TEXT NOT NULL DEFAULT '', error_signature TEXT NOT NULL DEFAULT '', environment TEXT NOT NULL DEFAULT '', preconditions TEXT NOT NULL DEFAULT '', outcome TEXT NOT NULL DEFAULT '', recovery_action TEXT NOT NULL DEFAULT '', payload_json TEXT NOT NULL DEFAULT '{}',  embedding TEXT NOT NULL DEFAULT '[]',  cluster_key TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_type_id ON interaction_event_embeddings (event_type, source_event_id);
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_failure ON interaction_event_embeddings (role, failure_mode);
CREATE TABLE IF NOT EXISTS code_calls (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  caller TEXT NOT NULL DEFAULT '',  callee TEXT NOT NULL DEFAULT '',  line INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_contents (  file_id INTEGER PRIMARY KEY REFERENCES files(id) ON DELETE CASCADE,  content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kb_runtime_state (  state_key TEXT PRIMARY KEY,  state_value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS notes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  title TEXT NOT NULL,  slug TEXT NOT NULL UNIQUE,  content TEXT NOT NULL,  tags TEXT NOT NULL DEFAULT '',  author TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS agent_hints (  id INTEGER PRIMARY KEY AUTOINCREMENT,  role TEXT NOT NULL,  pattern TEXT NOT NULL,  hint TEXT NOT NULL,  consumed INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS collab_rules (  id INTEGER PRIMARY KEY AUTOINCREMENT,  text TEXT NOT NULL,  reason TEXT NOT NULL DEFAULT '',  proposed_by TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'proposed',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  decided_at TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS collab_rules_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_documents (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL,  chunk_index INTEGER NOT NULL,  heading_path TEXT NOT NULL DEFAULT '',  line_start INTEGER NOT NULL DEFAULT 0,  line_end INTEGER NOT NULL DEFAULT 0,  content TEXT NOT NULL,  token_count INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')), prev_chunk_id INTEGER DEFAULT NULL, next_chunk_id INTEGER DEFAULT NULL,  chunk_strategy TEXT NOT NULL DEFAULT 'heading',  doc_kind TEXT NOT NULL DEFAULT '',  chunk_context TEXT NOT NULL DEFAULT '',  page_start INTEGER DEFAULT NULL,  page_end INTEGER DEFAULT NULL,  sensitivity_class TEXT NOT NULL DEFAULT '',  quarantine_state TEXT NOT NULL DEFAULT '',  tsr_state TEXT NOT NULL DEFAULT '');
-- structured-pdf Phase 1: per-line coordinate evidence index (see db2/schema.sql).
CREATE TABLE IF NOT EXISTS kb_doc_regions (  id INTEGER PRIMARY KEY AUTOINCREMENT,  chunk_id INTEGER NOT NULL REFERENCES kb_documents(id) ON DELETE CASCADE,  document_key TEXT NOT NULL DEFAULT '',  page_no INTEGER NOT NULL DEFAULT 0,  x0 REAL NOT NULL DEFAULT 0,  y0 REAL NOT NULL DEFAULT 0,  x1 REAL NOT NULL DEFAULT 0,  y1 REAL NOT NULL DEFAULT 0,  quote TEXT NOT NULL DEFAULT '',  line_index INTEGER NOT NULL DEFAULT 0,  content_type TEXT NOT NULL DEFAULT 'text',  sensitivity_class TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_table_cells (  id INTEGER PRIMARY KEY AUTOINCREMENT,  region_id INTEGER NOT NULL REFERENCES kb_doc_regions(id) ON DELETE CASCADE,  document_key TEXT NOT NULL DEFAULT '',  page_no INTEGER NOT NULL DEFAULT 0,  cell_row INTEGER NOT NULL DEFAULT 0,  cell_col INTEGER NOT NULL DEFAULT 0,  cell_text TEXT NOT NULL DEFAULT '',  subject TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  tsr_confidence INTEGER NOT NULL DEFAULT 0,  source_type TEXT NOT NULL DEFAULT 'table_cell',  sensitivity_class TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_kb_table_cells_dockey ON kb_table_cells (document_key, page_no);
CREATE INDEX IF NOT EXISTS idx_kb_table_cells_region ON kb_table_cells (region_id);
CREATE TABLE IF NOT EXISTS kb_doc_assets (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL DEFAULT '', generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  document_key TEXT NOT NULL DEFAULT '',  page_no INTEGER NOT NULL DEFAULT 0,  x0 REAL NOT NULL DEFAULT 0,  y0 REAL NOT NULL DEFAULT 0,  x1 REAL NOT NULL DEFAULT 0,  y1 REAL NOT NULL DEFAULT 0,  kind TEXT NOT NULL DEFAULT '',  caption TEXT NOT NULL DEFAULT '',  content_type TEXT NOT NULL DEFAULT 'image/png',  blob_ref TEXT NOT NULL DEFAULT '',  sensitivity_class TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_project ON kb_doc_assets (project, document_key);
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_dockey ON kb_doc_assets (document_key);
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_blob ON kb_doc_assets (blob_ref);
CREATE INDEX IF NOT EXISTS idx_kb_doc_regions_chunk ON kb_doc_regions (chunk_id, line_index);
CREATE INDEX IF NOT EXISTS idx_kb_doc_regions_dockey ON kb_doc_regions (document_key, page_no);
-- Polymorphic subject id: document jobs use kb_documents.id; memory_facts uses
-- memories.id. It intentionally has no single-table foreign key.
CREATE TABLE IF NOT EXISTS kb_async_jobs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  kind TEXT NOT NULL DEFAULT 'embed_raw',  document_id INTEGER NOT NULL,  project TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  claimed_by TEXT NOT NULL DEFAULT '',  claimed_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  next_attempt_at TEXT NOT NULL DEFAULT '',  UNIQUE(kind, document_id));
CREATE TABLE IF NOT EXISTS memory_aliases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  alias TEXT NOT NULL,  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, alias));
CREATE TABLE IF NOT EXISTS memory_entities (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  entity TEXT NOT NULL,  role TEXT NOT NULL DEFAULT 'mention',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, entity, role));
CREATE TABLE IF NOT EXISTS memory_temporal_refs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  ref_key TEXT NOT NULL,  granularity TEXT NOT NULL DEFAULT 'relative',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, ref_key, granularity));
CREATE TABLE IF NOT EXISTS memory_event_frames (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  actor TEXT NOT NULL DEFAULT '',  action TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  location TEXT NOT NULL DEFAULT '',  event_time TEXT NOT NULL DEFAULT '',  evidence_kind TEXT NOT NULL DEFAULT 'derived',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_summaries (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope TEXT NOT NULL DEFAULT 'headline',  summary TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, scope));
CREATE TABLE IF NOT EXISTS retrieval_shortcuts (  normalized_query TEXT PRIMARY KEY,  target_ids TEXT NOT NULL DEFAULT '',  hit_count INTEGER NOT NULL DEFAULT 0,  promoted INTEGER NOT NULL DEFAULT 0,  last_used_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_chunks (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  chunk_index INTEGER NOT NULL DEFAULT 0,  chunk_text TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, chunk_index));
CREATE TABLE IF NOT EXISTS memory_units (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  unit_type TEXT NOT NULL,  unit_key TEXT NOT NULL DEFAULT '',  unit_text TEXT NOT NULL,  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')), memory_kind TEXT NOT NULL DEFAULT 'episodic', is_episode_card INTEGER NOT NULL DEFAULT 0,  UNIQUE(memory_id, unit_type, unit_key, unit_text));
CREATE TABLE IF NOT EXISTS memory_unit_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  src_unit_id INTEGER NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  dst_unit_id INTEGER NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  edge_type TEXT NOT NULL DEFAULT 'related',  weight REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_episodes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_key TEXT NOT NULL,  episode_text TEXT NOT NULL,  source_session TEXT NOT NULL DEFAULT '',  reference_time TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_relations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_id INTEGER DEFAULT 0,  src_entity TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  dst_entity TEXT NOT NULL DEFAULT '',  fact_text TEXT NOT NULL DEFAULT '',  valid_at TEXT NOT NULL DEFAULT '',  invalid_at TEXT NOT NULL DEFAULT '',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_scopes (  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope_type TEXT NOT NULL,  scope_value TEXT NOT NULL,  PRIMARY KEY(memory_id, scope_type, scope_value));
CREATE TABLE IF NOT EXISTS entity_profiles (  entity_id TEXT NOT NULL PRIMARY KEY,  canonical_name TEXT NOT NULL,  observation_count INTEGER NOT NULL DEFAULT 0,  card_json TEXT NOT NULL DEFAULT '{}',  last_refreshed TEXT NOT NULL,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_lineage (  id INTEGER PRIMARY KEY AUTOINCREMENT,  object_type TEXT NOT NULL,  object_id INTEGER NOT NULL,  source_kind TEXT NOT NULL,  source_ref TEXT NOT NULL DEFAULT '',  ingested_at TEXT NOT NULL DEFAULT (datetime('now')),  confidence REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_scenes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  workspace_id TEXT NOT NULL DEFAULT '',  turn_count INTEGER NOT NULL DEFAULT 0,  noise_ratio REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_scene_members (  scene_id INTEGER NOT NULL REFERENCES memory_scenes(id) ON DELETE CASCADE,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  membership_strength REAL NOT NULL DEFAULT 1.0,  PRIMARY KEY(scene_id, memory_id));
CREATE TABLE IF NOT EXISTS memory_relation_schema (  id INTEGER PRIMARY KEY AUTOINCREMENT,  relation_id INTEGER NOT NULL,  subject_kind INTEGER NOT NULL DEFAULT 99,  object_kind  INTEGER NOT NULL DEFAULT 99);
CREATE TABLE IF NOT EXISTS memory_active_embedder (  id         INTEGER PRIMARY KEY CHECK (id = 1),  version    TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_reembed_progress (  id             INTEGER PRIMARY KEY CHECK (id = 1),  target_version TEXT    NOT NULL DEFAULT '',  last_id        INTEGER NOT NULL DEFAULT 0,  total          INTEGER NOT NULL DEFAULT 0,  done           INTEGER NOT NULL DEFAULT 0,  started_at     TEXT    NOT NULL DEFAULT (datetime('now')),  finished_at    TEXT    DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_coref_audit (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL DEFAULT 'none',  entity TEXT NOT NULL DEFAULT '',  mode TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS curator_invalidation_events (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_kind TEXT NOT NULL DEFAULT '',  source_id TEXT NOT NULL DEFAULT '',  artifacts_stale INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS code_index_ops (  point_id INTEGER PRIMARY KEY,  project TEXT NOT NULL DEFAULT '',  node_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS vector_index_ops (  point_id   INTEGER PRIMARY KEY,  collection TEXT    NOT NULL DEFAULT 'memory_units',  memory_id  INTEGER REFERENCES memories(id) ON DELETE CASCADE,  status     TEXT    NOT NULL DEFAULT 'pending',  attempts   INTEGER NOT NULL DEFAULT 0,  last_error TEXT    NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT    NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_promotion_approvals (  memory_id    INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_tier  TEXT    NOT NULL,  approver     TEXT    NOT NULL DEFAULT 'operator',  note         TEXT    NOT NULL DEFAULT '',  approved_at  TEXT    NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (memory_id, target_tier));
CREATE TABLE IF NOT EXISTS prospective_memories (  id INTEGER PRIMARY KEY AUTOINCREMENT,  trigger_text TEXT NOT NULL,  action_text TEXT NOT NULL,  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  recurrence TEXT NOT NULL DEFAULT 'once',  state TEXT NOT NULL DEFAULT 'armed',  valid_until TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  trigger_count INTEGER NOT NULL DEFAULT 0,  last_triggered_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS epistemic_directives (  id INTEGER PRIMARY KEY AUTOINCREMENT,  question TEXT NOT NULL,  topic TEXT NOT NULL DEFAULT '',  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  cause TEXT NOT NULL,  priority INTEGER NOT NULL DEFAULT 50,  state TEXT NOT NULL DEFAULT 'open',  memory_a_id INTEGER NOT NULL DEFAULT 0,  memory_b_id INTEGER NOT NULL DEFAULT 0,  resolution_memory_id INTEGER NOT NULL DEFAULT 0,  evidence TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  surfaced_count INTEGER NOT NULL DEFAULT 0,  last_surfaced_at TEXT NOT NULL DEFAULT '',  resolved_at TEXT NOT NULL DEFAULT '',  valid_until TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS failed_queries (  query_norm TEXT PRIMARY KEY,  failure_count INTEGER NOT NULL DEFAULT 0,  last_failed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS working_profile_state (  field TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '',  sample_count INTEGER NOT NULL DEFAULT 0,  confidence REAL NOT NULL DEFAULT 0.0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS working_profile_observations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  field TEXT NOT NULL,  value TEXT NOT NULL,  confidence REAL NOT NULL DEFAULT 0.5,  source_session TEXT NOT NULL DEFAULT '',  observed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS curiosity_items (  id INTEGER PRIMARY KEY AUTOINCREMENT,  gap_type TEXT NOT NULL,  target_entity TEXT NOT NULL DEFAULT '',  target_topic TEXT NOT NULL DEFAULT '',  evidence TEXT NOT NULL DEFAULT '',  importance REAL NOT NULL DEFAULT 0.0,  novelty REAL NOT NULL DEFAULT 0.0,  progress REAL NOT NULL DEFAULT 0.0,  routing_score REAL NOT NULL DEFAULT 0.0,  state TEXT NOT NULL DEFAULT 'open',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS learning_signals (  id INTEGER PRIMARY KEY AUTOINCREMENT,  signal_type TEXT NOT NULL,  source TEXT NOT NULL DEFAULT 'explicit',  polarity TEXT NOT NULL DEFAULT '',  title TEXT NOT NULL DEFAULT '',  description TEXT NOT NULL DEFAULT '',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id INTEGER NOT NULL DEFAULT 0,  correction_text TEXT NOT NULL DEFAULT '',  workflow_project TEXT NOT NULL DEFAULT '',  workflow_signal_type TEXT NOT NULL DEFAULT '',  evidence_refs TEXT NOT NULL DEFAULT '[]',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS learning_proposals (  id INTEGER PRIMARY KEY AUTOINCREMENT,  signal_id INTEGER NOT NULL REFERENCES learning_signals(id) ON DELETE CASCADE,  sink TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'pending',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id INTEGER NOT NULL DEFAULT 0,  action_json TEXT NOT NULL DEFAULT '{}',  evidence_refs TEXT NOT NULL DEFAULT '[]',  corroboration_count INTEGER NOT NULL DEFAULT 1,  expires_at TEXT NOT NULL DEFAULT '',  committed_at TEXT NOT NULL DEFAULT '',  archive_reason TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS learning_observations ( observation_id TEXT PRIMARY KEY, scope_kind TEXT NOT NULL DEFAULT 'workspace', scope_id TEXT NOT NULL DEFAULT '', observation_type TEXT NOT NULL CHECK (observation_type IN ('recurring_failure','failed_strategy','successful_recovery','missing_precondition','tool_misuse','environment_mismatch','unstable_procedure')), title TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'candidate' CHECK (status IN ('candidate','active','retired','rejected')), confidence REAL NOT NULL DEFAULT 0.0 CHECK (confidence >= 0.0 AND confidence <= 1.0), evidence_window_start TEXT NOT NULL DEFAULT '', evidence_window_end TEXT NOT NULL DEFAULT '', synthesis_policy_version TEXT NOT NULL, evidence_count INTEGER NOT NULL DEFAULT 0, independent_session_count INTEGER NOT NULL DEFAULT 0, supersedes TEXT NOT NULL DEFAULT '', superseded_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), refreshed_at TEXT NOT NULL DEFAULT (datetime('now')), retired_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS learning_observation_evidence ( observation_id TEXT NOT NULL REFERENCES learning_observations(observation_id) ON DELETE CASCADE, evidence_kind TEXT NOT NULL DEFAULT 'interaction_event', source_event_id INTEGER NOT NULL REFERENCES interaction_event_embeddings(source_event_id) ON DELETE CASCADE, source_span TEXT NOT NULL DEFAULT '', stance TEXT NOT NULL DEFAULT 'supports' CHECK (stance IN ('supports','contradicts')), observed_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (observation_id, evidence_kind, source_event_id, source_span, stance));
CREATE TABLE IF NOT EXISTS learning_application_events ( application_id TEXT PRIMARY KEY, source_event_id INTEGER NOT NULL REFERENCES interaction_event_embeddings(source_event_id) ON DELETE CASCADE, session_id TEXT NOT NULL DEFAULT '', scope_kind TEXT NOT NULL DEFAULT 'workspace', scope_id TEXT NOT NULL DEFAULT '', task_family TEXT NOT NULL DEFAULT '', observation_id TEXT NOT NULL DEFAULT '', procedure_artifact_id TEXT NOT NULL DEFAULT '', proposal_id INTEGER NOT NULL DEFAULT 0, retrieved INTEGER NOT NULL DEFAULT 0, rendered INTEGER NOT NULL DEFAULT 0, selected INTEGER NOT NULL DEFAULT 0, applied INTEGER NOT NULL DEFAULT 0, outcome TEXT NOT NULL DEFAULT 'unknown' CHECK (outcome IN ('unknown','success','failure','corrected','abandoned')), failure_class TEXT NOT NULL DEFAULT '', human_correction TEXT NOT NULL DEFAULT '', latency_ms INTEGER NOT NULL DEFAULT 0, tool_count INTEGER NOT NULL DEFAULT 0, turn_count INTEGER NOT NULL DEFAULT 0, token_count INTEGER NOT NULL DEFAULT 0, retrieved_refs TEXT NOT NULL DEFAULT '[]', rendered_refs TEXT NOT NULL DEFAULT '[]', selected_refs TEXT NOT NULL DEFAULT '[]', applied_refs TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_learning_application_procedure ON learning_application_events(procedure_artifact_id, applied, outcome, created_at);
CREATE INDEX IF NOT EXISTS idx_learning_application_observation ON learning_application_events(observation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_kb_async_jobs_status ON kb_async_jobs(status, id);
CREATE TABLE IF NOT EXISTS kb_ingest_queue (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  root_path TEXT NOT NULL,  workspace TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  force INTEGER NOT NULL DEFAULT 0,  priority INTEGER NOT NULL DEFAULT 0,  queued_at TEXT NOT NULL DEFAULT (datetime('now')),  started_at TEXT DEFAULT NULL,  completed_at TEXT DEFAULT NULL,  files_indexed INTEGER NOT NULL DEFAULT 0,  chunks_added INTEGER NOT NULL DEFAULT 0,  embeddings_added INTEGER NOT NULL DEFAULT 0,  error_message TEXT DEFAULT NULL);
CREATE INDEX IF NOT EXISTS idx_kb_ingest_queue_status ON kb_ingest_queue(status);
CREATE INDEX IF NOT EXISTS idx_kb_ingest_queue_claim ON kb_ingest_queue(status, priority DESC, id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_kb_ingest_queue_dedup ON kb_ingest_queue(project) WHERE status IN ('pending', 'running');
CREATE TABLE IF NOT EXISTS kb_file_index (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL,  ingested_at TEXT NOT NULL DEFAULT (datetime('now')),  content TEXT DEFAULT NULL,  UNIQUE(project, generation, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_file_index_project ON kb_file_index(project);
CREATE TABLE IF NOT EXISTS kb_code_unit_jobs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL DEFAULT '',  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT 'function',  line INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  claimed_by TEXT NOT NULL DEFAULT '',  claimed_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  next_attempt_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, file_path, symbol));
CREATE INDEX IF NOT EXISTS idx_kb_code_unit_jobs_status ON kb_code_unit_jobs(status, id);
CREATE INDEX IF NOT EXISTS idx_files_path ON files(path);
CREATE INDEX IF NOT EXISTS idx_terms_name ON terms(name);
CREATE INDEX IF NOT EXISTS idx_fi_name ON file_imports(name);
CREATE INDEX IF NOT EXISTS idx_fe_name ON file_exports(name);
CREATE INDEX IF NOT EXISTS idx_file_exports_file_id ON file_exports(file_id);
CREATE INDEX IF NOT EXISTS idx_file_imports_file_id ON file_imports(file_id);
CREATE INDEX IF NOT EXISTS idx_terms_file_id ON terms(file_id);
CREATE INDEX IF NOT EXISTS idx_code_calls_file_id ON code_calls(file_id);
CREATE INDEX IF NOT EXISTS idx_code_calls_callee ON code_calls(callee);
CREATE INDEX IF NOT EXISTS idx_ee_source ON entity_edges(source);
CREATE INDEX IF NOT EXISTS idx_ee_target ON entity_edges(target);
CREATE INDEX IF NOT EXISTS idx_mem_tier ON memories(tier);
CREATE INDEX IF NOT EXISTS idx_mem_kind ON memories(kind);
CREATE INDEX IF NOT EXISTS idx_mem_key ON memories(key);
CREATE INDEX IF NOT EXISTS idx_memories_sensitivity ON memories(sensitivity);
CREATE INDEX IF NOT EXISTS idx_mp_mem ON memory_provenance(memory_id);
CREATE INDEX IF NOT EXISTS idx_mc_unresolved ON memory_conflicts(resolved) WHERE resolved = 0;
CREATE INDEX IF NOT EXISTS idx_tasks_state ON tasks(state);
CREATE INDEX IF NOT EXISTS idx_tasks_parent ON tasks(parent_id);
CREATE INDEX IF NOT EXISTS idx_te_source ON task_edges(source_id);
CREATE INDEX IF NOT EXISTS idx_te_target ON task_edges(target_id);
CREATE INDEX IF NOT EXISTS idx_dl_task ON decision_log(task_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_dl_active_scope ON decision_log(subject, linked_policy_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_dl_revisit ON decision_log(revisit_when) WHERE status = 'active' AND revisit_when != '';
CREATE INDEX IF NOT EXISTS idx_agent_hints_lookup ON agent_hints(role, consumed);
CREATE INDEX IF NOT EXISTS idx_memory_workspaces_workspace ON memory_workspaces(workspace);
CREATE INDEX IF NOT EXISTS idx_memory_aliases_memory ON memory_aliases(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_aliases_alias ON memory_aliases(alias);
CREATE INDEX IF NOT EXISTS idx_memory_entities_entity ON memory_entities(entity);
CREATE INDEX IF NOT EXISTS idx_memory_entities_memory ON memory_entities(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_temporal_refs_ref ON memory_temporal_refs(ref_key);
CREATE INDEX IF NOT EXISTS idx_memory_temporal_refs_memory ON memory_temporal_refs(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_event_frames_actor ON memory_event_frames(actor);
CREATE INDEX IF NOT EXISTS idx_memory_event_frames_action ON memory_event_frames(action);
CREATE INDEX IF NOT EXISTS idx_memory_event_frames_event_time ON memory_event_frames(event_time);
CREATE INDEX IF NOT EXISTS idx_memory_event_frames_memory ON memory_event_frames(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_summaries_scope ON memory_summaries(scope);
CREATE INDEX IF NOT EXISTS idx_retrieval_shortcuts_promoted ON retrieval_shortcuts(promoted, updated_at);
CREATE INDEX IF NOT EXISTS idx_memory_chunks_memory ON memory_chunks(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_units_memory ON memory_units(memory_id);
CREATE INDEX IF NOT EXISTS idx_memory_units_type ON memory_units(unit_type);
CREATE INDEX IF NOT EXISTS idx_memory_units_key ON memory_units(unit_key);
CREATE INDEX IF NOT EXISTS idx_memory_unit_edges_src ON memory_unit_edges(src_unit_id);
CREATE INDEX IF NOT EXISTS idx_memory_unit_edges_dst ON memory_unit_edges(dst_unit_id);
CREATE INDEX IF NOT EXISTS idx_memory_unit_edges_type ON memory_unit_edges(edge_type);
CREATE INDEX IF NOT EXISTS idx_kb_documents_project ON kb_documents(project, generation, file_path);
CREATE INDEX IF NOT EXISTS idx_memory_units_kind ON memory_units(memory_kind);
CREATE INDEX IF NOT EXISTS idx_memory_units_kind_key ON memory_units(memory_kind, unit_key);
CREATE INDEX IF NOT EXISTS idx_entity_profiles_refreshed  ON entity_profiles(last_refreshed);
CREATE INDEX IF NOT EXISTS idx_kb_docs_prev  ON kb_documents(prev_chunk_id) WHERE prev_chunk_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_kb_docs_next  ON kb_documents(next_chunk_id) WHERE next_chunk_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ml_object ON memory_lineage(object_type, object_id);
CREATE INDEX IF NOT EXISTS idx_msm_memory ON memory_scene_members(memory_id);
CREATE INDEX IF NOT EXISTS idx_mrs_rel ON memory_relation_schema(relation_id);
CREATE INDEX IF NOT EXISTS idx_mca_memory ON memory_coref_audit(memory_id);
CREATE INDEX IF NOT EXISTS idx_mca_session ON memory_coref_audit(session_id);
CREATE INDEX IF NOT EXISTS idx_vio_status    ON vector_index_ops(status);
CREATE INDEX IF NOT EXISTS idx_vio_memory_id ON vector_index_ops(memory_id);
CREATE TABLE IF NOT EXISTS evidence_index_ops (  artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE,  collection TEXT NOT NULL DEFAULT 'evidence',  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_evidence_index_ops_status ON evidence_index_ops(status);
CREATE TABLE IF NOT EXISTS learning_synth_ops (  artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE,  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_learning_synth_ops_status ON learning_synth_ops(status);
CREATE INDEX IF NOT EXISTS idx_mpa_target ON memory_promotion_approvals(target_tier);
CREATE INDEX IF NOT EXISTS idx_prospective_state ON prospective_memories(state);
CREATE INDEX IF NOT EXISTS idx_prospective_state_valid  ON prospective_memories(state, valid_until);
CREATE INDEX IF NOT EXISTS idx_prospective_anchor_entity  ON prospective_memories(anchor_entity) WHERE anchor_entity != '';
CREATE INDEX IF NOT EXISTS idx_prospective_anchor_file  ON prospective_memories(anchor_file) WHERE anchor_file != '';
CREATE INDEX IF NOT EXISTS idx_memories_lifecycle_ttl  ON memories(lifecycle_state, ttl_at);
CREATE INDEX IF NOT EXISTS idx_memories_lifecycle  ON memories(lifecycle_state);
CREATE INDEX IF NOT EXISTS idx_directives_state  ON epistemic_directives(state);
CREATE INDEX IF NOT EXISTS idx_directives_state_priority  ON epistemic_directives(state, priority DESC);
CREATE INDEX IF NOT EXISTS idx_directives_anchor_entity  ON epistemic_directives(anchor_entity) WHERE anchor_entity != '';
CREATE INDEX IF NOT EXISTS idx_directives_anchor_file  ON epistemic_directives(anchor_file) WHERE anchor_file != '';
CREATE INDEX IF NOT EXISTS idx_directives_cause  ON epistemic_directives(cause);
CREATE UNIQUE INDEX IF NOT EXISTS idx_directives_dedup_contradiction  ON epistemic_directives(memory_a_id, memory_b_id)  WHERE cause = 'contradiction' AND memory_a_id != 0 AND memory_b_id != 0;
CREATE UNIQUE INDEX IF NOT EXISTS idx_directives_dedup_topic  ON epistemic_directives(cause, topic)  WHERE topic != '' AND cause IN ('retrieval_failure', 'missing_config');
CREATE INDEX IF NOT EXISTS idx_memories_cognified_kind  ON memories(cognified_memory_kind) WHERE cognified_memory_kind != '';
CREATE INDEX IF NOT EXISTS idx_working_profile_obs_field  ON working_profile_observations(field);
CREATE INDEX IF NOT EXISTS idx_working_profile_obs_field_value  ON working_profile_observations(field, value);
CREATE INDEX IF NOT EXISTS idx_curiosity_state  ON curiosity_items(state);
CREATE INDEX IF NOT EXISTS idx_curiosity_gap_type  ON curiosity_items(gap_type);
CREATE INDEX IF NOT EXISTS idx_curiosity_target  ON curiosity_items(target_entity, target_topic)  WHERE target_entity != '' OR target_topic != '';
CREATE UNIQUE INDEX IF NOT EXISTS idx_curiosity_dedup_missing_fact  ON curiosity_items(gap_type, target_topic)  WHERE gap_type = 'missing_fact' AND target_topic != '' AND state = 'open';
CREATE INDEX IF NOT EXISTS idx_learning_signals_type  ON learning_signals(signal_type, created_at);
CREATE INDEX IF NOT EXISTS idx_learning_proposals_state  ON learning_proposals(state, sink, created_at);
CREATE INDEX IF NOT EXISTS idx_learning_proposals_target  ON learning_proposals(sink, target_key, target_memory_id)  WHERE state = 'pending';
CREATE INDEX IF NOT EXISTS idx_learning_observations_scope ON learning_observations(scope_kind, scope_id, status, observation_type);
CREATE INDEX IF NOT EXISTS idx_learning_observation_evidence_source ON learning_observation_evidence(source_event_id, observation_id);
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_ai AFTER INSERT ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(rowid, chunk_text) VALUES (new.id, new.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_ad AFTER DELETE ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(memory_chunks_fts, rowid, chunk_text)  VALUES('delete', old.id, old.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_au AFTER UPDATE ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(memory_chunks_fts, rowid, chunk_text)  VALUES('delete', old.id, old.chunk_text);  INSERT INTO memory_chunks_fts(rowid, chunk_text) VALUES (new.id, new.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_ai AFTER INSERT ON memory_units BEGIN  INSERT INTO memory_units_fts(rowid, unit_key, unit_text)  VALUES (new.id, new.unit_key, new.unit_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_ad AFTER DELETE ON memory_units BEGIN  INSERT INTO memory_units_fts(memory_units_fts, rowid, unit_key, unit_text)  VALUES('delete', old.id, old.unit_key, old.unit_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_au AFTER UPDATE ON memory_units BEGIN  INSERT INTO memory_units_fts(memory_units_fts, rowid, unit_key, unit_text)  VALUES('delete', old.id, old.unit_key, old.unit_text);  INSERT INTO memory_units_fts(rowid, unit_key, unit_text)  VALUES (new.id, new.unit_key, new.unit_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_ai AFTER INSERT ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(rowid, trigger_text)  VALUES (new.id, new.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_ad AFTER DELETE ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(prospective_memories_fts, rowid, trigger_text)  VALUES ('delete', old.id, old.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_au AFTER UPDATE ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(prospective_memories_fts, rowid, trigger_text)  VALUES ('delete', old.id, old.trigger_text);  INSERT INTO prospective_memories_fts(rowid, trigger_text)  VALUES (new.id, new.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_ai AFTER INSERT ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(rowid, question, topic)  VALUES (new.id, new.question, new.topic);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_ad AFTER DELETE ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(epistemic_directives_fts, rowid, question, topic)  VALUES ('delete', old.id, old.question, old.topic);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_au AFTER UPDATE ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(epistemic_directives_fts, rowid, question, topic)  VALUES ('delete', old.id, old.question, old.topic);  INSERT INTO epistemic_directives_fts(rowid, question, topic)  VALUES (new.id, new.question, new.topic);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_ai AFTER INSERT ON memories BEGIN  INSERT INTO memories_code_fts(rowid, key, content)  VALUES (new.id, new.key, new.content);  INSERT INTO memories_fts(rowid, key, content, use_cases)  VALUES (new.id, new.key, new.content, new.use_cases);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_ad AFTER DELETE ON memories BEGIN  INSERT INTO memories_code_fts(memories_code_fts, rowid, key, content)  VALUES('delete', old.id, old.key, old.content);  INSERT INTO memories_fts(memories_fts, rowid, key, content, use_cases)  VALUES('delete', old.id, old.key, old.content, old.use_cases);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_au AFTER UPDATE ON memories BEGIN  INSERT INTO memories_code_fts(memories_code_fts, rowid, key, content)  VALUES('delete', old.id, old.key, old.content);  INSERT INTO memories_code_fts(rowid, key, content)  VALUES (new.id, new.key, new.content);  INSERT INTO memories_fts(memories_fts, rowid, key, content, use_cases)  VALUES('delete', old.id, old.key, old.content, old.use_cases);  INSERT INTO memories_fts(rowid, key, content, use_cases)  VALUES (new.id, new.key, new.content, new.use_cases);END;
CREATE TRIGGER IF NOT EXISTS code_fts_ai AFTER INSERT ON file_contents BEGIN  INSERT INTO code_fts(rowid, content)  VALUES (new.file_id, new.content);END;
CREATE TRIGGER IF NOT EXISTS code_fts_ad AFTER DELETE ON file_contents BEGIN  INSERT INTO code_fts(code_fts, rowid, content)  VALUES('delete', old.file_id, old.content);END;
CREATE TRIGGER IF NOT EXISTS code_fts_au AFTER UPDATE ON file_contents BEGIN  INSERT INTO code_fts(code_fts, rowid, content)  VALUES('delete', old.file_id, old.content);  INSERT INTO code_fts(rowid, content)  VALUES (new.file_id, new.content);END;
INSERT OR IGNORE INTO tool_registry VALUES('bash','Run a shell command and capture stdout/stderr.','{"type":"object","properties":{"command":{"type":"string"},    "timeout_ms":{"type":"integer"}},"required":["command"]}','','write',0,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('read_file','Read a file from disk.','{"type":"object","properties":{"path":{"type":"string"},    "offset":{"type":"integer"},"limit":{"type":"integer"}},    "required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('write_file','Write a file to disk.','{"type":"object","properties":{"path":{"type":"string"},    "content":{"type":"string"}},"required":["path","content"]}','','write',0,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('list_files','List files in a directory.','{"type":"object","properties":{"path":{"type":"string"},    "pattern":{"type":"string"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('verify','Verify an expected condition.','{"type":"object","properties":{"check_type":{"type":"string"},    "target":{"type":"string"},"expected":{"type":"string"}},    "required":["check_type","target"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('git_log','Show recent git commits.','{"type":"object","properties":{"path":{"type":"string"},    "count":{"type":"integer"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('grep','Search files with a regex pattern.','{"type":"object","properties":{"path":{"type":"string"},    "pattern":{"type":"string"},"max_results":{"type":"integer"}},    "required":["path","pattern"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('git_diff','Show git diff output.','{"type":"object","properties":{"path":{"type":"string"},    "ref":{"type":"string"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('git_status','Show git working tree status.','{"type":"object","properties":{"path":{"type":"string"}},    "required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('env_get','Read a specific environment variable.','{"type":"object","properties":{"name":{"type":"string"}},    "required":["name"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('test','Check file properties.','{"type":"object","properties":{"path":{"type":"string"},    "check":{"type":"string"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('request_input','Request human input during delegated execution.','{"type":"object","properties":{"question":{"type":"string"}},    "required":["question"]}','','write',0,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('code_search','Search indexed code semantically or by symbol.','{"type":"object","properties":{"query":{"type":"string"},    "project":{"type":"string"},"max_results":{"type":"integer"}},    "required":["query"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('find_symbol','Look up the exact definition location of a C symbol, function, type, or macro in the indexed codebase.','{"type":"object","properties":{"identifier":{"type":"string"}},    "required":["identifier"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('search_memory','Search aimee knowledge base for stored facts, prior decisions, and project context.','{"type":"object","properties":{"query":{"type":"string"}},    "required":["query"]}','','read',1,1,'');
