CREATE TABLE IF NOT EXISTS sketch_store (  id INTEGER PRIMARY KEY AUTOINCREMENT,  sketch_kind TEXT NOT NULL,  scope_kind TEXT NOT NULL,  scope_id TEXT NOT NULL DEFAULT '',  feature_family TEXT NOT NULL,  state_bytes BLOB NOT NULL,  item_count INTEGER NOT NULL DEFAULT 0,  params_json TEXT NOT NULL DEFAULT '{}',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (sketch_kind, scope_kind, scope_id, feature_family));
CREATE TABLE IF NOT EXISTS kb_minhash_signatures (  project TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL DEFAULT '',  signature_bytes BLOB NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (project, generation, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_minhash_signatures_project ON kb_minhash_signatures(project);
CREATE TABLE IF NOT EXISTS kb_lsh_buckets (  project TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  band INTEGER NOT NULL,  band_hash TEXT NOT NULL,  file_path TEXT NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (project, generation, band, band_hash, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_lsh_buckets_lookup ON kb_lsh_buckets(project, band, band_hash);
CREATE TABLE IF NOT EXISTS artifacts (  id TEXT NOT NULL PRIMARY KEY,  kind TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'proposed',  scope_kind TEXT NOT NULL DEFAULT 'user',  scope_id TEXT NOT NULL DEFAULT '',  operator_id TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  attempt_count INTEGER NOT NULL DEFAULT 1,  source_bundle_hash TEXT NOT NULL DEFAULT '',  model_version TEXT NOT NULL DEFAULT '',  prompt_version TEXT NOT NULL DEFAULT '',  target_surface TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  committed_at TEXT NOT NULL DEFAULT '',  retired_at TEXT NOT NULL DEFAULT '',  superseded_by TEXT NOT NULL DEFAULT '',  last_accessed_at TEXT DEFAULT NULL,  last_decay_at TEXT DEFAULT NULL,  reflected_at TEXT DEFAULT NULL,  turn_id TEXT DEFAULT NULL CHECK (turn_id IS NULL OR length(turn_id) <= 128),  payload TEXT NOT NULL DEFAULT '{}');
-- This file is the FRESH-INIT shim schema (applied to a new :memory: db per test);
-- it is never applied in-place to a pre-existing db, so the inline turn_id column
-- is always present before this index. Production upgrades run via schema.sql's
-- idempotent ALTER ... ADD COLUMN IF NOT EXISTS (Postgres).
CREATE UNIQUE INDEX IF NOT EXISTS idx_artifacts_turn_event ON artifacts (turn_id) WHERE kind = 'retrieval_event' AND turn_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_artifacts_kind_state ON artifacts (kind, state);
CREATE INDEX IF NOT EXISTS idx_artifacts_scope ON artifacts (scope_kind, scope_id);
CREATE INDEX IF NOT EXISTS idx_artifacts_retrieval_attr ON artifacts (kind, scope_id);
CREATE INDEX IF NOT EXISTS idx_artifacts_demotion_profile ON artifacts (kind, target_surface, scope_kind, scope_id);
CREATE TABLE IF NOT EXISTS artifact_citations (  artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  source_kind TEXT NOT NULL,  source_id TEXT NOT NULL,  span_start INTEGER NOT NULL DEFAULT 0,  span_end INTEGER NOT NULL DEFAULT 0,  PRIMARY KEY (artifact_id, source_kind, source_id, span_start, span_end));
CREATE TABLE IF NOT EXISTS artifact_links (  from_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  to_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  kind TEXT NOT NULL,  PRIMARY KEY (from_id, to_id, kind));
CREATE TABLE IF NOT EXISTS audit_events (  id TEXT NOT NULL PRIMARY KEY,  source_artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  target_surface TEXT NOT NULL,  target_id TEXT NOT NULL,  operator_id TEXT NOT NULL DEFAULT '',  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  before_snapshot TEXT,  after_snapshot TEXT,  applied_at TEXT NOT NULL DEFAULT (datetime('now')),  applied_confidence REAL NOT NULL DEFAULT 1.0,  flagged_for_review INTEGER NOT NULL DEFAULT 0,  reviewed_at TEXT NOT NULL DEFAULT '',  verdict TEXT NOT NULL DEFAULT '',  verdict_tag TEXT NOT NULL DEFAULT '',  verdict_scope TEXT NOT NULL DEFAULT '',  counter_example TEXT NOT NULL DEFAULT '',  verdict_note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_audit_events_artifact ON audit_events (source_artifact_id);
CREATE TABLE IF NOT EXISTS feature_rows (  subject_id TEXT NOT NULL,  subject_kind TEXT NOT NULL,  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  feature_set_version TEXT NOT NULL,  features TEXT NOT NULL DEFAULT '{}',  computed_at TEXT NOT NULL,  PRIMARY KEY (subject_id, subject_kind, feature_set_version));
CREATE INDEX IF NOT EXISTS idx_feature_rows_kind_ts ON feature_rows (subject_kind, computed_at);
CREATE TABLE IF NOT EXISTS report_enrichments (  subject_type TEXT NOT NULL,  subject_id TEXT NOT NULL,  enrichment_kind TEXT NOT NULL,  source TEXT NOT NULL DEFAULT '',  schema_version TEXT NOT NULL,  payload_json TEXT NOT NULL DEFAULT '{}',  input_hash TEXT NOT NULL DEFAULT '',  computed_at TEXT NOT NULL,  expires_at TEXT NOT NULL DEFAULT '',  PRIMARY KEY (subject_type, subject_id, enrichment_kind, source, schema_version));
CREATE INDEX IF NOT EXISTS idx_report_enrichments_subject ON report_enrichments (subject_type, subject_id);
CREATE INDEX IF NOT EXISTS idx_report_enrichments_kind_ts ON report_enrichments (enrichment_kind, computed_at);
CREATE INDEX IF NOT EXISTS idx_audit_events_surface ON audit_events (target_surface, applied_at);
CREATE TABLE IF NOT EXISTS bandit_decisions (  id TEXT NOT NULL PRIMARY KEY,  decision_point TEXT NOT NULL,  arm_id TEXT NOT NULL,  context_hash TEXT NOT NULL DEFAULT '',  propensity REAL NOT NULL DEFAULT 1.0,  reward REAL,  decided_at TEXT NOT NULL,  closed_at TEXT NOT NULL DEFAULT '',  is_exploration INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_point ON bandit_decisions (decision_point, arm_id, decided_at);
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_explore ON bandit_decisions (decision_point, decided_at, is_exploration);
CREATE TABLE IF NOT EXISTS bandit_arm_stats (  decision_point TEXT NOT NULL,  arm_id TEXT NOT NULL,  n_decisions INTEGER NOT NULL DEFAULT 0,  n_rewards INTEGER NOT NULL DEFAULT 0,  sum_reward REAL NOT NULL DEFAULT 0.0,  sum_reward_sq REAL NOT NULL DEFAULT 0.0,  posterior_alpha REAL NOT NULL DEFAULT 1.0,  posterior_beta REAL NOT NULL DEFAULT 1.0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (decision_point, arm_id));
CREATE TABLE IF NOT EXISTS bandit_promotions (  decision_point TEXT NOT NULL PRIMARY KEY,  arm_id TEXT NOT NULL,  rollback_arm TEXT NOT NULL DEFAULT '',  promoted_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_maintenance_runs (  id TEXT NOT NULL PRIMARY KEY,  rows_decayed INTEGER NOT NULL DEFAULT 0,  orphans_pruned INTEGER NOT NULL DEFAULT 0,  elapsed_ms INTEGER NOT NULL DEFAULT 0,  lambda REAL NOT NULL DEFAULT 0.005,  confidence_floor REAL NOT NULL DEFAULT 0.10,  dry_run INTEGER NOT NULL DEFAULT 0,  run_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS docs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  content_hash TEXT NOT NULL,  filename TEXT NOT NULL DEFAULT '',  scope TEXT NOT NULL DEFAULT 'global',  converter TEXT NOT NULL DEFAULT 'passthrough',  converter_version TEXT NOT NULL DEFAULT '',  normalized_text TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'staged',  review_needed INTEGER NOT NULL DEFAULT 0,  review_reason TEXT NOT NULL DEFAULT '',  doc_type TEXT NOT NULL DEFAULT '',  doc_type_confidence REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (content_hash, converter, converter_version, scope));
CREATE INDEX IF NOT EXISTS idx_docs_state_review ON docs (state, review_needed);
CREATE INDEX IF NOT EXISTS idx_docs_content_hash ON docs (content_hash);
CREATE INDEX IF NOT EXISTS idx_docs_doc_type ON docs (doc_type);
CREATE TABLE IF NOT EXISTS document_sections (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  parent_id INTEGER REFERENCES document_sections(id) ON DELETE CASCADE,  ordinal INTEGER NOT NULL DEFAULT 0,  depth INTEGER NOT NULL DEFAULT 0,  heading TEXT NOT NULL DEFAULT '',  heading_path TEXT NOT NULL DEFAULT '',  span_start INTEGER NOT NULL DEFAULT 0,  span_end INTEGER NOT NULL DEFAULT 0,  content_hash TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (doc_id, heading_path, ordinal));
CREATE INDEX IF NOT EXISTS idx_document_sections_doc ON document_sections (doc_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_document_sections_parent ON document_sections (parent_id);
CREATE TABLE IF NOT EXISTS document_references (  id INTEGER PRIMARY KEY AUTOINCREMENT,  from_doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  from_section_id INTEGER REFERENCES document_sections(id) ON DELETE SET NULL,  ref_type TEXT NOT NULL DEFAULT 'mentions',  raw_target TEXT NOT NULL DEFAULT '',  to_doc_id INTEGER REFERENCES docs(id) ON DELETE SET NULL,  resolution TEXT NOT NULL DEFAULT 'unresolved',  confidence REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (from_doc_id, ref_type, raw_target));
CREATE INDEX IF NOT EXISTS idx_doc_refs_from ON document_references (from_doc_id);
CREATE INDEX IF NOT EXISTS idx_doc_refs_to ON document_references (to_doc_id) WHERE to_doc_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_doc_refs_resolution ON document_references (resolution);
CREATE TABLE IF NOT EXISTS corpus_processing_jobs (  doc_id INTEGER PRIMARY KEY REFERENCES docs(id) ON DELETE CASCADE,  content_hash TEXT NOT NULL DEFAULT '',  stage TEXT NOT NULL DEFAULT 'ingested',  stage_status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  lease_owner TEXT NOT NULL DEFAULT '',  lease_until TEXT NOT NULL DEFAULT '',  last_error TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_corpus_jobs_status ON corpus_processing_jobs (stage_status, stage, doc_id);
CREATE TABLE IF NOT EXISTS corpus_stage_events (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  from_stage TEXT NOT NULL DEFAULT '',  to_stage TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL DEFAULT '',  detail TEXT NOT NULL DEFAULT '',  worker TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_corpus_stage_events_doc ON corpus_stage_events (doc_id, id);
CREATE TABLE IF NOT EXISTS document_versions (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_key TEXT NOT NULL,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  content_hash TEXT NOT NULL DEFAULT '',  version_no INTEGER NOT NULL DEFAULT 1,  source_mtime TEXT NOT NULL DEFAULT '',  source_time TEXT NOT NULL DEFAULT '',  source_time_provenance TEXT NOT NULL DEFAULT 'unknown',  is_current INTEGER NOT NULL DEFAULT 1,  superseded_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (doc_key, content_hash));
CREATE INDEX IF NOT EXISTS idx_document_versions_current ON document_versions (doc_key, is_current);
CREATE TABLE IF NOT EXISTS doc_releases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL UNIQUE,  state TEXT NOT NULL DEFAULT 'pending',  promoted_at TEXT NOT NULL DEFAULT '',  retired_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_doc_releases_state ON doc_releases (state);
CREATE TABLE IF NOT EXISTS release_docs (  release_id INTEGER NOT NULL REFERENCES doc_releases(id) ON DELETE CASCADE,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  accepted_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (release_id, doc_id));
CREATE INDEX IF NOT EXISTS idx_release_docs_doc_id ON release_docs (doc_id);
CREATE TABLE IF NOT EXISTS memory_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  record_type TEXT NOT NULL DEFAULT '',  primary_scope TEXT NOT NULL DEFAULT '',  workspace TEXT NOT NULL DEFAULT '',  project TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  project TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_pdf_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  project TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS curator_entity_vectors (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  canonical_name TEXT NOT NULL DEFAULT '',  artifact_id TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_entity_vectors_scope ON curator_entity_vectors (scope_kind, scope_id);
CREATE TABLE IF NOT EXISTS curator_narrative_vectors (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT '',  doc_id TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT '',  priority TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_narrative_vectors_kind ON curator_narrative_vectors (kind, status, priority);
CREATE TABLE IF NOT EXISTS curator_claim_vectors (  point_id INTEGER PRIMARY KEY,  subj_attr_vec TEXT NOT NULL DEFAULT '[]',  value_vec TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  subject TEXT NOT NULL DEFAULT '',  attribute TEXT NOT NULL DEFAULT '',  value TEXT NOT NULL DEFAULT '',  claim_kind TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_claim_vectors_kind ON curator_claim_vectors (claim_kind);
CREATE TABLE IF NOT EXISTS curator_code_unit_vectors (  point_id INTEGER PRIMARY KEY,  intent_vec TEXT NOT NULL DEFAULT '[]',  signature_vec TEXT NOT NULL DEFAULT '[]',  body_vec TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  def_kind TEXT NOT NULL DEFAULT '',  signature TEXT NOT NULL DEFAULT '',  body_hash TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_kind ON curator_code_unit_vectors (def_kind);
CREATE TABLE IF NOT EXISTS exemplar_vectors (  id INTEGER PRIMARY KEY AUTOINCREMENT,  artifact_id TEXT NOT NULL,  collection TEXT NOT NULL DEFAULT 'case_exemplars',  embedding TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_artifact_id ON exemplar_vectors (artifact_id);
CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_collection  ON exemplar_vectors (collection);
CREATE TABLE IF NOT EXISTS evidence_vectors (  id INTEGER PRIMARY KEY AUTOINCREMENT,  artifact_id TEXT NOT NULL,  collection TEXT NOT NULL DEFAULT 'evidence',  embedding TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_evidence_vectors_artifact_id ON evidence_vectors (artifact_id);
CREATE INDEX IF NOT EXISTS idx_evidence_vectors_collection  ON evidence_vectors (collection);
CREATE TABLE IF NOT EXISTS reasoning_rulesets (  id TEXT NOT NULL PRIMARY KEY,  version INTEGER NOT NULL DEFAULT 1,  name TEXT NOT NULL DEFAULT '',  content_hash TEXT NOT NULL DEFAULT '',  active INTEGER NOT NULL DEFAULT 1,  rules TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_reasoning_rulesets_active ON reasoning_rulesets (active, name);
CREATE TABLE IF NOT EXISTS memory_recall_shadow_deltas (  id INTEGER PRIMARY KEY AUTOINCREMENT,  query_hash TEXT NOT NULL,  project TEXT NOT NULL DEFAULT '',  mode TEXT NOT NULL DEFAULT 'shadow',  result_count INTEGER NOT NULL DEFAULT 0,  delta_json TEXT NOT NULL DEFAULT '{}',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_mrsd_query_created ON memory_recall_shadow_deltas(query_hash, created_at);
CREATE INDEX IF NOT EXISTS idx_mrsd_project_created ON memory_recall_shadow_deltas(project, created_at);
CREATE TABLE IF NOT EXISTS entity_nodes (  node_key TEXT PRIMARY KEY,  node_kind INTEGER NOT NULL DEFAULT 0,  project TEXT NOT NULL DEFAULT '',  display_name TEXT NOT NULL DEFAULT '',  full_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  node_origin TEXT NOT NULL DEFAULT '',  last_seen_generation_id INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_entity_nodes_project ON entity_nodes(project);
CREATE INDEX IF NOT EXISTS idx_entity_nodes_kind ON entity_nodes(node_kind);
CREATE TABLE IF NOT EXISTS entity_node_aliases (  alias TEXT NOT NULL,  node_key TEXT NOT NULL REFERENCES entity_nodes(node_key) ON DELETE CASCADE,  alias_kind TEXT NOT NULL DEFAULT '',  project TEXT NOT NULL DEFAULT '',  last_seen_generation_id INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (alias, node_key));
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_alias ON entity_node_aliases(alias);
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_project_alias ON entity_node_aliases(project, alias);
CREATE TABLE IF NOT EXISTS code_projection_generations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','visible','superseded','aborted')),  source_hash TEXT NOT NULL DEFAULT '',  edge_count INTEGER NOT NULL DEFAULT 0,  node_count INTEGER NOT NULL DEFAULT 0,  started_at TEXT NOT NULL DEFAULT (datetime('now')),  visible_at TEXT NOT NULL DEFAULT '',  aborted_at TEXT NOT NULL DEFAULT '',  error TEXT NOT NULL DEFAULT '',  extractor_version TEXT NOT NULL DEFAULT '',  pipeline_version TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_cpg_project_state ON code_projection_generations(project, state);
CREATE TABLE IF NOT EXISTS code_projection_edges (  generation_id INTEGER NOT NULL REFERENCES code_projection_generations(id) ON DELETE CASCADE,  project TEXT NOT NULL,  source TEXT NOT NULL,  relation TEXT NOT NULL,  target TEXT NOT NULL,  source_hash TEXT NOT NULL DEFAULT '',  PRIMARY KEY (generation_id, source, relation, target));
CREATE INDEX IF NOT EXISTS idx_cpe_project_triple ON code_projection_edges(project, source, relation, target);
CREATE TABLE IF NOT EXISTS code_projection_communities (  generation_id INTEGER NOT NULL REFERENCES code_projection_generations(id) ON DELETE CASCADE,  project TEXT NOT NULL,  node_id TEXT NOT NULL,  community_id TEXT NOT NULL,  PRIMARY KEY (generation_id, node_id));
CREATE INDEX IF NOT EXISTS idx_cpc_gen_community ON code_projection_communities(generation_id, community_id);
CREATE TABLE IF NOT EXISTS lessons_outcome_ledger (  id INTEGER PRIMARY KEY AUTOINCREMENT,  session_id TEXT NOT NULL DEFAULT '',  turn_id TEXT NOT NULL DEFAULT '',  project_id TEXT NOT NULL DEFAULT '',  generation_id INTEGER NOT NULL DEFAULT 0,  answer_outcome TEXT NOT NULL CHECK (answer_outcome IN ('useful','dead_end','corrected')),  correction_text TEXT NOT NULL DEFAULT '',  finding_id TEXT NOT NULL DEFAULT '',  actor_id TEXT NOT NULL DEFAULT '',  actor_source TEXT NOT NULL DEFAULT 'agent' CHECK (actor_source IN ('user','reviewer','agent')),  confirmed INTEGER NOT NULL DEFAULT 0,  confirmed_by TEXT NOT NULL DEFAULT '',  confirmed_at TEXT NOT NULL DEFAULT '',  ts TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_lessons_ledger_project ON lessons_outcome_ledger(project_id);
CREATE INDEX IF NOT EXISTS idx_lessons_ledger_finding ON lessons_outcome_ledger(finding_id);
CREATE TABLE IF NOT EXISTS lessons_outcome_citations (  outcome_id INTEGER NOT NULL REFERENCES lessons_outcome_ledger(id) ON DELETE CASCADE,  node_id TEXT NOT NULL,  disposition TEXT NOT NULL DEFAULT 'unused' CHECK (disposition IN ('useful','stale','unused')),  PRIMARY KEY (outcome_id, node_id));
CREATE TRIGGER IF NOT EXISTS trg_lessons_ledger_no_delete BEFORE DELETE ON lessons_outcome_ledger BEGIN  SELECT RAISE(ABORT, 'lessons_outcome_ledger is append-only (DELETE forbidden)');END;
CREATE TRIGGER IF NOT EXISTS trg_lessons_ledger_immutable BEFORE UPDATE OF id, session_id, turn_id, project_id, generation_id, answer_outcome, correction_text, finding_id, actor_id, actor_source, ts ON lessons_outcome_ledger BEGIN  SELECT RAISE(ABORT, 'lessons_outcome_ledger is append-only (only the confirmation flag may change)');END;
CREATE INDEX IF NOT EXISTS idx_ee_source_relation ON entity_edges(source, relation);
CREATE INDEX IF NOT EXISTS idx_ee_target_relation ON entity_edges(target, relation);
CREATE INDEX IF NOT EXISTS idx_ee_origin_source ON entity_edges(edge_origin, source);
CREATE INDEX IF NOT EXISTS idx_ee_projection_generation ON entity_edges(projection_generation_id, source, relation);
-- Cross-repo dependency graph (sqlite shim mirror of schema.sql; see that file for design notes).
-- Per-dialect deltas vs schema.sql: evidence is TEXT here (JSONB on Postgres); timestamps use
-- datetime('now'); ids are AUTOINCREMENT. Table set is kept in parity by schema-sync-check.
CREATE INDEX IF NOT EXISTS idx_projects_trust ON projects(trust);
CREATE TABLE IF NOT EXISTS cross_repo_meta (  id INTEGER PRIMARY KEY CHECK (id = 1),  trust_epoch INTEGER NOT NULL DEFAULT 0 CHECK (trust_epoch >= 0),  repo_set_hash TEXT NOT NULL DEFAULT '',  blocked_symbols_version INTEGER NOT NULL DEFAULT 0 CHECK (blocked_symbols_version >= 0),  review_overflow_dropped INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
-- INSERT OR IGNORE only guarantees the singleton row exists; it must not clobber live runtime counters on re-apply (see schema.sql).
INSERT OR IGNORE INTO cross_repo_meta (id) VALUES (1);
CREATE TABLE IF NOT EXISTS blocked_symbols (  word TEXT NOT NULL,  lang TEXT NOT NULL DEFAULT '',  reason TEXT NOT NULL DEFAULT '',  version INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (word, lang));
CREATE INDEX IF NOT EXISTS idx_blocked_symbols_version ON blocked_symbols(version);
CREATE TABLE IF NOT EXISTS cross_repo_review_queue (  id INTEGER PRIMARY KEY AUTOINCREMENT,  repo_set_hash TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL,  caller_repo TEXT NOT NULL,  candidate_definer TEXT NOT NULL DEFAULT '',  evidence TEXT NOT NULL DEFAULT '{}',  evidence_score REAL NOT NULL DEFAULT 0.0,  arrival_seq INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'accepted', 'rejected')),  review_class TEXT NOT NULL DEFAULT 'ambiguous' CHECK (review_class IN ('ambiguous', 'ffi')),  cross_lang INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (repo_set_hash, symbol, caller_repo, candidate_definer));
CREATE INDEX IF NOT EXISTS idx_crrq_evict_open ON cross_repo_review_queue(evidence_score, arrival_seq) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_crrq_caller ON cross_repo_review_queue(caller_repo, status);
CREATE TABLE IF NOT EXISTS cross_repo_trust_audit (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  actor TEXT NOT NULL DEFAULT '',  prior_trust TEXT NOT NULL DEFAULT '' CHECK (prior_trust IN ('', 'trusted', 'untrusted')),  new_trust TEXT NOT NULL DEFAULT '' CHECK (new_trust IN ('', 'trusted', 'untrusted')),  trust_epoch_before INTEGER NOT NULL DEFAULT 0,  trust_epoch_after INTEGER NOT NULL DEFAULT 0,  repo_set_hash TEXT NOT NULL DEFAULT '',  request_id TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_crta_project ON cross_repo_trust_audit(project, created_at);
CREATE TABLE IF NOT EXISTS cross_repo_identity (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  kind TEXT NOT NULL,  value TEXT NOT NULL,  UNIQUE(project, kind, value));
CREATE INDEX IF NOT EXISTS idx_cri_lookup ON cross_repo_identity(kind, value);
CREATE TABLE IF NOT EXISTS cross_repo_route (  id INTEGER PRIMARY KEY AUTOINCREMENT,  caller_project TEXT NOT NULL,  definer_project TEXT NOT NULL,  kind TEXT NOT NULL,  confidence TEXT NOT NULL DEFAULT 'medium',  evidence TEXT NOT NULL DEFAULT '',  UNIQUE(caller_project, definer_project, kind, evidence));
CREATE INDEX IF NOT EXISTS idx_crr_caller ON cross_repo_route(caller_project);
CREATE INDEX IF NOT EXISTS idx_crr_definer ON cross_repo_route(definer_project);
CREATE TABLE IF NOT EXISTS cross_repo_build_dep (  id INTEGER PRIMARY KEY AUTOINCREMENT,  caller_project TEXT NOT NULL,  definer_project TEXT NOT NULL,  build_kind TEXT NOT NULL DEFAULT '',  parse_confidence TEXT NOT NULL DEFAULT 'high',  evidence TEXT NOT NULL DEFAULT '',  UNIQUE(caller_project, definer_project, build_kind, evidence));
CREATE INDEX IF NOT EXISTS idx_crbd_caller ON cross_repo_build_dep(caller_project);
CREATE TABLE IF NOT EXISTS code_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  project TEXT NOT NULL DEFAULT '',  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  node_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  record_type TEXT NOT NULL DEFAULT 'code_unit',  content_hash TEXT NOT NULL DEFAULT '',  body_hash TEXT NOT NULL DEFAULT '',  source_hash TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_code_embeddings_project ON code_embeddings(project);
CREATE INDEX IF NOT EXISTS idx_code_embeddings_node ON code_embeddings(project, generation, node_key);
CREATE UNIQUE INDEX IF NOT EXISTS idx_code_embeddings_hash ON code_embeddings(project, generation, node_key, content_hash);
CREATE INDEX IF NOT EXISTS idx_code_embeddings_body_hash ON code_embeddings(project, body_hash);
-- CSS migration assistant (WP-B): style graph (sqlite shim mirror of schema.sql).
CREATE TABLE IF NOT EXISTS css_rules (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  selector TEXT NOT NULL DEFAULT '',  spec_a INTEGER NOT NULL DEFAULT 0,  spec_b INTEGER NOT NULL DEFAULT 0,  spec_c INTEGER NOT NULL DEFAULT 0,  spec_uncertain INTEGER NOT NULL DEFAULT 0,  at_context TEXT NOT NULL DEFAULT '',  line INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS css_declarations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  rule_id INTEGER NOT NULL REFERENCES css_rules(id) ON DELETE CASCADE,  property TEXT NOT NULL DEFAULT '',  value TEXT NOT NULL DEFAULT '',  important INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_css_rules_file ON css_rules(file_id);
CREATE INDEX IF NOT EXISTS idx_css_rules_selector ON css_rules(selector);
CREATE INDEX IF NOT EXISTS idx_css_decl_rule ON css_declarations(rule_id);
CREATE INDEX IF NOT EXISTS idx_css_decl_property ON css_declarations(property);
-- CSS migration assistant (WP-D): component -> style join (sqlite shim mirror).
CREATE TABLE IF NOT EXISTS css_component_styles (  id INTEGER PRIMARY KEY AUTOINCREMENT,  component_file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  class_token TEXT NOT NULL DEFAULT '',  rule_id INTEGER NOT NULL DEFAULT -1,  resolved INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_css_comp_file ON css_component_styles(component_file_id);
CREATE INDEX IF NOT EXISTS idx_css_comp_token ON css_component_styles(class_token);
-- CSS migration assistant (WP-F): per-unit pipeline state (sqlite shim mirror).
CREATE TABLE IF NOT EXISTS css_migration_units (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL DEFAULT '',  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  unit_path TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'pending',  total_tokens INTEGER NOT NULL DEFAULT 0,  resolved_tokens INTEGER NOT NULL DEFAULT 0,  oracle_equivalent INTEGER NOT NULL DEFAULT -1,  note TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, unit_path));
CREATE INDEX IF NOT EXISTS idx_css_migration_project ON css_migration_units(project, state);
CREATE TABLE IF NOT EXISTS css_render_snapshots (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL DEFAULT '',  generation INTEGER NOT NULL DEFAULT 1 CHECK (generation > 0),  unit_path TEXT NOT NULL DEFAULT '',  phase TEXT NOT NULL DEFAULT '',  snapshot TEXT NOT NULL DEFAULT '',  content_hash TEXT NOT NULL DEFAULT '',  captured_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, unit_path, phase));
CREATE INDEX IF NOT EXISTS idx_css_render_snapshots_unit ON css_render_snapshots(project, unit_path);
-- Typed-fact knowledge layer (first slice; sqlite shim mirror).
CREATE TABLE IF NOT EXISTS typed_facts (  id INTEGER PRIMARY KEY AUTOINCREMENT,  subject TEXT NOT NULL DEFAULT '',  subject_kind TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  object_kind TEXT NOT NULL DEFAULT '',  confidence INTEGER NOT NULL DEFAULT 50,  source TEXT NOT NULL DEFAULT '',  asserted_at TEXT NOT NULL DEFAULT '',  active INTEGER NOT NULL DEFAULT 1,  superseded_by INTEGER NOT NULL DEFAULT -1);
CREATE INDEX IF NOT EXISTS idx_typed_facts_subject ON typed_facts(subject, relation, active);
CREATE INDEX IF NOT EXISTS idx_typed_facts_relation ON typed_facts(relation, active);
-- P10 kb credential vault (sqlite shim mirror of schema.sql: columns only; the RLS
-- and SECURITY DEFINER envelope machinery is Postgres-only, so the shim carries no
-- vault definer functions — the pg backend requires a real Postgres to operate).
CREATE TABLE IF NOT EXISTS org_vault_salt (  principal TEXT PRIMARY KEY,  salt BLOB NOT NULL,  kek_check BLOB NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_vault_control (  singleton INTEGER PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),  sealed INTEGER NOT NULL DEFAULT 0,  seal_epoch INTEGER NOT NULL DEFAULT 1 CHECK (seal_epoch > 0),  maintenance_kind TEXT NOT NULL DEFAULT '',  maintenance_id TEXT NOT NULL DEFAULT '',  fencing_token INTEGER NOT NULL DEFAULT 1 CHECK (fencing_token > 0),  last_opened_rewrap_fence INTEGER NOT NULL DEFAULT 0 CHECK (last_opened_rewrap_fence >= 0 AND last_opened_rewrap_fence <= fencing_token),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  CHECK ((maintenance_kind = '') = (maintenance_id = '')),  CHECK (sealed = 1 OR (maintenance_kind = '' AND maintenance_id = '')));
INSERT OR IGNORE INTO kb_vault_control(singleton) VALUES (1);
CREATE TABLE IF NOT EXISTS org_vault_secret (  id INTEGER PRIMARY KEY AUTOINCREMENT,  principal TEXT NOT NULL,  team_id INTEGER,  agent TEXT NOT NULL DEFAULT '',  cred TEXT NOT NULL DEFAULT '',  version INTEGER NOT NULL,  wrapped_dek BLOB NOT NULL,  nonce BLOB NOT NULL,  ciphertext BLOB NOT NULL,  tag BLOB NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(principal, agent, cred, version));
CREATE INDEX IF NOT EXISTS idx_org_vault_secret_team ON org_vault_secret(team_id);
CREATE INDEX IF NOT EXISTS idx_org_vault_secret_slot ON org_vault_secret(principal, agent, cred);
CREATE TABLE IF NOT EXISTS org_vault_key_use_intent (team_id INTEGER NOT NULL, authenticated_origin TEXT NOT NULL, use_id TEXT NOT NULL, key_id TEXT NOT NULL, principal TEXT NOT NULL, agent TEXT NOT NULL DEFAULT '', cred TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL, request_digest TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, operation TEXT NOT NULL, seal_epoch INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(team_id, authenticated_origin, use_id));
-- P5-B1 status authority persistence shape only. All fixed-slot admission,
-- WORM, seal and role enforcement remains PostgreSQL-only and fails closed on
-- the SQLite shim.
CREATE TABLE IF NOT EXISTS kb_management_status_key (singleton INTEGER PRIMARY KEY, bootstrap_id TEXT NOT NULL UNIQUE, custody_key_id TEXT NOT NULL UNIQUE, wire_key_id TEXT NOT NULL UNIQUE, public_key BLOB NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_management_status_key_use_intent (use_id TEXT PRIMARY KEY, custody_key_id TEXT NOT NULL, wire_key_id TEXT NOT NULL, version INTEGER NOT NULL, request_digest TEXT NOT NULL, hwm_attestation_digest TEXT NOT NULL, caller_issuer TEXT NOT NULL, caller_serial_norm TEXT NOT NULL, caller_fingerprint TEXT NOT NULL, target_server_id TEXT NOT NULL, target_mgmt_fingerprint TEXT NOT NULL, revocation_generation INTEGER NOT NULL, seal_epoch INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
-- P5-C2a management-token trust-root persistence shape only. All fixed-slot
-- transitions, custody and WORM enforcement are PostgreSQL-only.
CREATE TABLE IF NOT EXISTS kb_management_token_root (root_kind TEXT PRIMARY KEY, bootstrap_id TEXT NOT NULL UNIQUE, custody_key_id TEXT NOT NULL UNIQUE, wire_id TEXT NOT NULL UNIQUE, public_key BLOB NOT NULL, public_exponent BLOB NOT NULL, public_digest BLOB NOT NULL, jwk_digest BLOB NOT NULL, current_version INTEGER NOT NULL DEFAULT 1, initial_seal_epoch INTEGER NOT NULL, v1_envelope_digest BLOB NOT NULL, v2_envelope_digest BLOB NOT NULL, hwm2_attestation_digest BLOB, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_management_jwks_publication_root (singleton INTEGER PRIMARY KEY, custody_key_id TEXT NOT NULL UNIQUE, helper TEXT NOT NULL, verifier_domain TEXT NOT NULL, identity_digest BLOB NOT NULL, hwm1_attestation BLOB NOT NULL, hwm1_attestation_digest BLOB NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_management_token_root_vault_permit (backend_pid INTEGER NOT NULL, transaction_id INTEGER NOT NULL, root_kind TEXT NOT NULL, PRIMARY KEY(backend_pid,transaction_id,root_kind));
CREATE TABLE IF NOT EXISTS kb_management_jwks_publication_candidate (generation INTEGER PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE, phase TEXT NOT NULL, valid_from INTEGER NOT NULL, valid_until INTEGER NOT NULL, previous_manifest_sha256 BLOB NOT NULL, jwks_bytes BLOB NOT NULL, jwks_sha256 BLOB NOT NULL, payload_bytes BLOB NOT NULL, payload_sha256 BLOB NOT NULL, envelope_bytes BLOB NOT NULL, envelope_sha256 BLOB NOT NULL, manifest_sha256 BLOB NOT NULL, signature BLOB NOT NULL, token_wire_id TEXT NOT NULL, token_public_digest BLOB NOT NULL, token_jwk_digest BLOB NOT NULL, manifest_wire_id TEXT NOT NULL, manifest_public_digest BLOB NOT NULL, publication_identity_digest BLOB NOT NULL, hwm1_attestation_digest BLOB NOT NULL, hwm2_attestation_digest BLOB, seal_epoch INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), finalized_at TEXT);
CREATE TABLE IF NOT EXISTS kb_management_jwks_publication_generation (generation INTEGER PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE, valid_from INTEGER NOT NULL, valid_until INTEGER NOT NULL, previous_manifest_sha256 BLOB NOT NULL, jwks_bytes BLOB NOT NULL, payload_bytes BLOB NOT NULL, envelope_bytes BLOB NOT NULL, envelope_sha256 BLOB NOT NULL, manifest_sha256 BLOB NOT NULL, jwks_sha256 BLOB NOT NULL, payload_sha256 BLOB NOT NULL, signature BLOB NOT NULL, manifest_wire_id TEXT NOT NULL, manifest_public_digest BLOB NOT NULL, token_wire_id TEXT NOT NULL, token_public_digest BLOB NOT NULL, token_jwk_digest BLOB NOT NULL, publication_identity_digest BLOB NOT NULL, hwm1_attestation_digest BLOB NOT NULL, hwm2_attestation_digest BLOB NOT NULL, seal_epoch INTEGER NOT NULL, finalized_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kb_management_jwks_publication_registry (singleton INTEGER PRIMARY KEY, current_generation INTEGER NOT NULL, candidate_id TEXT NOT NULL UNIQUE, manifest_sha256 BLOB NOT NULL, envelope_sha256 BLOB NOT NULL, hwm2_attestation_digest BLOB NOT NULL, finalized_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kb_management_jwks_manifest_key_use_intent (use_id TEXT PRIMARY KEY, generation INTEGER NOT NULL, candidate_id TEXT NOT NULL, custody_key_id TEXT NOT NULL, manifest_wire_id TEXT NOT NULL, version INTEGER NOT NULL, payload_sha256 BLOB NOT NULL, hwm_attestation_digest BLOB NOT NULL, seal_epoch INTEGER NOT NULL, purpose TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(generation,candidate_id,seal_epoch));
CREATE TABLE IF NOT EXISTS kb_management_jwks_publication_permit (backend_pid INTEGER NOT NULL, transaction_id INTEGER NOT NULL, operation TEXT NOT NULL, PRIMARY KEY(backend_pid,transaction_id,operation));
CREATE TABLE IF NOT EXISTS org_vault_current (  principal TEXT NOT NULL,  agent TEXT NOT NULL DEFAULT '',  cred TEXT NOT NULL DEFAULT '',  version INTEGER NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (principal, agent, cred));
CREATE TABLE IF NOT EXISTS org_vault_rotation (  id INTEGER PRIMARY KEY AUTOINCREMENT,  key_id TEXT NOT NULL,  principal TEXT NOT NULL,  team_id INTEGER,  agent TEXT NOT NULL DEFAULT '',  cred TEXT NOT NULL DEFAULT '',  from_version INTEGER NOT NULL,  to_version INTEGER NOT NULL,  state TEXT NOT NULL,  compromise INTEGER NOT NULL DEFAULT 0,  hwm_attestation BLOB,  old_vendor_ref TEXT NOT NULL DEFAULT '',  new_vendor_ref TEXT NOT NULL DEFAULT '',  revoke_receipt TEXT NOT NULL DEFAULT '',  failure_phase TEXT NOT NULL DEFAULT '',  claim_owner TEXT NOT NULL DEFAULT '',  claim_token INTEGER NOT NULL DEFAULT 0,  claim_until TEXT,  last_error TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(principal, agent, cred, to_version));

-- P7-reseal-d1 whole-vault re-wrap persistence (sqlite shim: columns only).
-- The fenced transaction API, RLS, WORM triggers, and promotion machinery are
-- PostgreSQL-only; production callers must fail closed on this shim.
CREATE TABLE IF NOT EXISTS kb_vault_rewrap_operation (  operation_id TEXT PRIMARY KEY,  request_id TEXT NOT NULL UNIQUE,  actor TEXT NOT NULL,  state TEXT NOT NULL,  seal_epoch INTEGER NOT NULL,  fencing_token INTEGER NOT NULL,  old_generation INTEGER NOT NULL,  new_generation INTEGER NOT NULL,  receipt BLOB,  receipt_digest BLOB,  secret_count INTEGER NOT NULL DEFAULT 0,  check_count INTEGER NOT NULL DEFAULT 0,  inventory_digest BLOB,  stage_digest BLOB,  failure_class TEXT NOT NULL DEFAULT '',  failure_from_state TEXT,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
DROP INDEX IF EXISTS idx_kb_vault_rewrap_one_active;
CREATE UNIQUE INDEX idx_kb_vault_rewrap_one_active ON kb_vault_rewrap_operation((1)) WHERE state NOT IN ('aborted','recovery_required','completed');
CREATE UNIQUE INDEX IF NOT EXISTS idx_kb_vault_rewrap_fencing_token ON kb_vault_rewrap_operation(fencing_token);
CREATE TABLE IF NOT EXISTS kb_vault_rewrap_dek_stage (  operation_id TEXT NOT NULL REFERENCES kb_vault_rewrap_operation(operation_id) ON DELETE CASCADE,  source_id INTEGER NOT NULL,  principal TEXT NOT NULL,  agent TEXT NOT NULL,  cred TEXT NOT NULL,  version INTEGER NOT NULL,  source_digest BLOB NOT NULL,  new_wrapped_dek BLOB NOT NULL,  PRIMARY KEY(operation_id,source_id),  UNIQUE(operation_id,principal,agent,cred,version));
CREATE TABLE IF NOT EXISTS kb_vault_rewrap_check_stage (  operation_id TEXT NOT NULL REFERENCES kb_vault_rewrap_operation(operation_id) ON DELETE CASCADE,  principal TEXT NOT NULL,  source_digest BLOB NOT NULL,  new_kek_check BLOB NOT NULL,  PRIMARY KEY(operation_id,principal));
CREATE TABLE IF NOT EXISTS kb_vault_rewrap_worm (  operation_id TEXT NOT NULL REFERENCES kb_vault_rewrap_operation(operation_id),  event_kind TEXT NOT NULL,  event_id TEXT NOT NULL UNIQUE,  state TEXT NOT NULL,  seal_epoch INTEGER NOT NULL,  fencing_token INTEGER NOT NULL,  receipt_digest BLOB,  inventory_digest BLOB,  stage_digest BLOB,  actor TEXT NOT NULL,  detail TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY(operation_id,event_kind));
-- D3b sealed-to-open acknowledgement (sqlite shim: columns only).  The WORM
-- triggers and authoritative mutation functions remain PostgreSQL-only.
CREATE TABLE IF NOT EXISTS kb_vault_open_event (  event_id TEXT PRIMARY KEY,  event_kind TEXT NOT NULL,  operation_id TEXT REFERENCES kb_vault_rewrap_operation(operation_id),  request_id TEXT NOT NULL UNIQUE,  actor TEXT NOT NULL,  operation_fence INTEGER,  opened_epoch INTEGER NOT NULL UNIQUE,  opened_fence INTEGER NOT NULL UNIQUE,  row_hash BLOB NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(event_kind,operation_id));
-- P7-witness-e1 evidence store (sqlite shim: columns only; WORM triggers, digest
-- and append functions remain PostgreSQL-only).
CREATE TABLE IF NOT EXISTS kb_vault_witness_shard (  tenant TEXT NOT NULL,  provider TEXT NOT NULL,  seq INTEGER NOT NULL DEFAULT 0,  head_hash BLOB NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY(tenant,provider));
CREATE TABLE IF NOT EXISTS kb_vault_witness_log (  tenant TEXT NOT NULL,  provider TEXT NOT NULL,  shard_seq INTEGER NOT NULL,  source_kind INTEGER NOT NULL,  source_id TEXT NOT NULL,  source_hash BLOB NOT NULL,  has_source_pred INTEGER NOT NULL,  source_pred_hash BLOB NOT NULL,  witness_pred_hash BLOB NOT NULL,  record_hash BLOB NOT NULL,  request_id TEXT NOT NULL DEFAULT '',  principal TEXT NOT NULL DEFAULT '',  provider_cred TEXT NOT NULL DEFAULT '',  group_id TEXT NOT NULL DEFAULT '',  event_ts TEXT NOT NULL,  seal_epoch INTEGER NOT NULL,  fencing_token INTEGER NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY(tenant,provider,shard_seq));
CREATE TABLE IF NOT EXISTS kb_vault_witness_checkpoint (  seq INTEGER PRIMARY KEY,  root BLOB NOT NULL,  has_predecessor INTEGER NOT NULL,  predecessor_digest BLOB NOT NULL,  shard_count INTEGER NOT NULL,  leaf_snapshot BLOB NOT NULL,  leaf_snapshot_digest BLOB NOT NULL,  signer_key_id BLOB NOT NULL,  sig_alg INTEGER NOT NULL,  sig_version INTEGER NOT NULL,  signature BLOB NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_vault_witness_emit_cursor (  kind INTEGER NOT NULL,  tenant TEXT NOT NULL,  provider TEXT NOT NULL,  last_emitted INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY(kind,tenant,provider));

-- P2a org model catalog + entitlement (sqlite shim mirror of schema.sql: columns
-- only; RLS, the SECURITY DEFINER catalog CRUD + org_catalog_entitled(), and the WORM
-- audit append are Postgres-only, so every P2a runtime path is gated by
-- db2_tenant_require_pg() and hard-fails on the shim rather than reading unprotected).
CREATE TABLE IF NOT EXISTS org_model_catalog (  id INTEGER PRIMARY KEY AUTOINCREMENT,  model_id TEXT NOT NULL UNIQUE,  display_name TEXT NOT NULL DEFAULT '',  provider TEXT NOT NULL,  wire TEXT NOT NULL,  endpoint TEXT NOT NULL DEFAULT '',  enabled INTEGER NOT NULL DEFAULT 1,  bedrock_api TEXT,  model_family TEXT,  bedrock_target_type TEXT,  aws_partition TEXT,  aws_account TEXT,  aws_region_set TEXT,  underlying_fm_arns TEXT,  created_at TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS org_model_entitlement (  id INTEGER PRIMARY KEY AUTOINCREMENT,  model_id TEXT NOT NULL REFERENCES org_model_catalog(model_id),  team_id INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  created_at TEXT NOT NULL DEFAULT '',  UNIQUE(model_id, team_id));
CREATE INDEX IF NOT EXISTS idx_org_ent_team ON org_model_entitlement(team_id);
CREATE INDEX IF NOT EXISTS idx_org_ent_model ON org_model_entitlement(model_id);

-- P4a budget reservation core (sqlite shim mirror of schema.sql: columns only; RLS, the
-- expression UNIQUE INDEXes, the atomic SECURITY DEFINER reserve/settle/set/show, and
-- the WORM audit append are Postgres-only, so every P4a runtime path is gated by
-- db2_tenant_require_pg() and hard-fails on the shim rather than reserving unprotected).
CREATE TABLE IF NOT EXISTS org_budget (  id INTEGER PRIMARY KEY AUTOINCREMENT,  team_id INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  project_id INTEGER REFERENCES kb_project(id) ON DELETE CASCADE,  period TEXT NOT NULL,  limit_usd TEXT NOT NULL,  soft_limit_usd TEXT,  created_at TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS org_budget_counter (  id INTEGER PRIMARY KEY AUTOINCREMENT,  team_id INTEGER NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  project_id INTEGER REFERENCES kb_project(id) ON DELETE CASCADE,  period TEXT NOT NULL,  period_id TEXT NOT NULL,  spend_usd TEXT NOT NULL DEFAULT '0',  reserved_usd TEXT NOT NULL DEFAULT '0',  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS org_budget_reservation (  id INTEGER PRIMARY KEY AUTOINCREMENT,  request_id TEXT NOT NULL,  origin_cert_cn TEXT NOT NULL,  team_id INTEGER NOT NULL REFERENCES kb_team(id),  project_id INTEGER REFERENCES kb_project(id),  pricing_version INTEGER NOT NULL,  reserved_max_usd TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'admitted',  lease_expires_at TEXT NOT NULL DEFAULT '',  realized_usd TEXT,  created_at TEXT NOT NULL DEFAULT '',  settled_at TEXT NOT NULL DEFAULT '',  UNIQUE(origin_cert_cn, request_id));
CREATE TABLE IF NOT EXISTS org_budget_reservation_alloc (  id INTEGER PRIMARY KEY AUTOINCREMENT,  reservation_id INTEGER NOT NULL REFERENCES org_budget_reservation(id) ON DELETE CASCADE,  counter_key TEXT NOT NULL,  period TEXT NOT NULL,  period_id TEXT NOT NULL,  reserved_usd TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_org_budget_alloc_resv ON org_budget_reservation_alloc(reservation_id);

-- P4b keyed fixed-window rate limiter (schema-sync mirror only). The RLS + the atomic
-- lock-all/check-all/bump SECURITY DEFINER org_rate_check and the WORM-audited
-- org_rate_policy_set are Postgres-only, so every P4b runtime path is gated by
-- db2_tenant_require_pg() and hard-fails on the shim rather than rate-limiting unsafely.
CREATE TABLE IF NOT EXISTS org_rate_policy (  id INTEGER PRIMARY KEY AUTOINCREMENT,  dim TEXT NOT NULL,  scope_key TEXT NOT NULL,  window_seconds INTEGER NOT NULL,  max_count INTEGER NOT NULL,  created_at TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_org_rate_policy_key ON org_rate_policy(dim, scope_key);
CREATE TABLE IF NOT EXISTS org_rate_window (  dim_key TEXT NOT NULL,  window_id TEXT NOT NULL,  count INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT '',  PRIMARY KEY (dim_key, window_id));

-- P9a telemetry export + content-free ingest target (schema-sync mirror only).
-- The RLS + the allowlist-gated fail-closed SECURITY DEFINER org_telemetry_ingest,
-- the WORM-audited org_telemetry_allow, and the org_metrics_snapshot aggregate are
-- Postgres-only, so every P9a runtime path is gated by db2_tenant_require_pg() and
-- hard-fails on the shim rather than ingesting/exporting unsafely.
CREATE TABLE IF NOT EXISTS org_telemetry (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_event_id TEXT NOT NULL,  origin_cert_cn TEXT NOT NULL,  team_id INTEGER REFERENCES kb_team(id),  event_schema TEXT NOT NULL,  metric_name TEXT NOT NULL,  metric_kind TEXT NOT NULL,  value TEXT NOT NULL DEFAULT '0',  ts INTEGER NOT NULL,  created_at TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_org_telemetry_source ON org_telemetry(source_event_id);
CREATE INDEX IF NOT EXISTS idx_org_telemetry_team_created ON org_telemetry(team_id, created_at);
CREATE TABLE IF NOT EXISTS org_telemetry_allowlist (  event_schema TEXT PRIMARY KEY,  metric_names TEXT NOT NULL,  enabled INTEGER NOT NULL DEFAULT 1,  updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_cert_revocation_generation (singleton INTEGER PRIMARY KEY CHECK(singleton=1), generation INTEGER NOT NULL CHECK(generation>=1), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
INSERT OR IGNORE INTO kb_cert_revocation_generation(singleton,generation) VALUES(1,1);
CREATE TABLE IF NOT EXISTS kb_server_registry (  server_id TEXT PRIMARY KEY, cert_cn TEXT NOT NULL UNIQUE, mgmt_cert_cn TEXT NOT NULL UNIQUE, owner_issuer TEXT NOT NULL DEFAULT '', owner_subject TEXT NOT NULL DEFAULT '', team_id INTEGER NOT NULL, endpoint TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', health TEXT NOT NULL DEFAULT '', version TEXT NOT NULL DEFAULT '', last_seen TEXT, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', client_issuer TEXT NOT NULL DEFAULT '', client_serial_norm TEXT NOT NULL DEFAULT '', client_fingerprint TEXT NOT NULL DEFAULT '', mgmt_issuer TEXT NOT NULL DEFAULT '', mgmt_serial_norm TEXT NOT NULL DEFAULT '', mgmt_fingerprint TEXT NOT NULL DEFAULT '', enrollment_op TEXT NOT NULL DEFAULT '', client_csr_digest TEXT NOT NULL DEFAULT '', mgmt_csr_digest TEXT NOT NULL DEFAULT '', activation_expires_at TEXT);
CREATE INDEX IF NOT EXISTS idx_kb_server_registry_team ON kb_server_registry(team_id);
-- Per-user /v1 write authorization shape mirror (proposal §6).  The composite
-- (server_id,team_id) foreign key and the RLS policies live only in the
-- Postgres schema; the CHECKs that keep a malformed tier or subject out of the
-- table are mirrored so shim-backed unit tests exercise the same rejections.
CREATE TABLE IF NOT EXISTS kb_write_tier_grant (server_id TEXT NOT NULL, team_id INTEGER NOT NULL, subject TEXT NOT NULL CHECK(length(subject) BETWEEN 1 AND 576), tier TEXT NOT NULL CHECK(tier IN ('off','data','full')), granted_by TEXT NOT NULL CHECK(length(granted_by) BETWEEN 1 AND 576), created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', revoked_at TEXT, PRIMARY KEY(server_id,team_id,subject));
CREATE INDEX IF NOT EXISTS idx_kb_write_tier_grant_live ON kb_write_tier_grant(server_id,team_id,subject) WHERE revoked_at IS NULL;
-- P5-B2b shape mirrors only.  RLS, transition functions, audit and primary
-- authority are PostgreSQL-only and callers fail closed on this shim.
CREATE TABLE IF NOT EXISTS kb_management_instance_grant (installation_id TEXT PRIMARY KEY, replacement_operation_id TEXT UNIQUE, replacement_lineage_id TEXT NOT NULL, replaces_installation_id TEXT, team_id INTEGER NOT NULL, workload_issuer TEXT NOT NULL, workload_subject TEXT NOT NULL, proof_anchor TEXT NOT NULL, custody_anchor TEXT NOT NULL, binding_digest TEXT NOT NULL, expected_ca_issuer TEXT NOT NULL, expected_ca_fingerprint TEXT NOT NULL, creator_identity TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT '', expires_at TEXT NOT NULL, consumed_at TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS kb_management_instance (installation_id TEXT PRIMARY KEY, replacement_lineage_id TEXT NOT NULL, authority_id TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, workload_issuer TEXT NOT NULL, workload_subject TEXT NOT NULL, proof_anchor TEXT NOT NULL, custody_anchor TEXT NOT NULL, binding_digest TEXT NOT NULL, expected_ca_issuer TEXT NOT NULL, expected_ca_fingerprint TEXT NOT NULL, current_generation INTEGER NOT NULL DEFAULT 0, current_enrollment_id INTEGER, state TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', revoked_at TEXT, replaced_at TEXT);
CREATE TABLE IF NOT EXISTS kb_management_instance_issue (operation_id TEXT PRIMARY KEY, installation_id TEXT NOT NULL, issue_kind TEXT NOT NULL, generation INTEGER NOT NULL, previous_enrollment_id INTEGER, previous_cert_issuer TEXT, previous_cert_serial_norm TEXT, previous_cert_fingerprint TEXT, csr_digest TEXT NOT NULL, csr_spki_digest TEXT NOT NULL, public_bundle_digest TEXT, cert_issuer TEXT, cert_serial_norm TEXT, cert_fingerprint TEXT, cert_spki_digest TEXT, cert_not_before TEXT, cert_not_after TEXT, enrollment_id INTEGER, state TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT '', pending_expires_at TEXT NOT NULL, activated_at TEXT, terminal_at TEXT, UNIQUE(installation_id,generation));
-- P5-C1c shape-only compatibility.  SQLite has no authoritative admission or
-- outcome functions: production management action journaling requires PostgreSQL.
CREATE TABLE IF NOT EXISTS kb_management_token_intent_namespace (correlation_id TEXT NOT NULL UNIQUE, jti TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '', UNIQUE(correlation_id,jti,kind));
CREATE TABLE IF NOT EXISTS kb_management_action_intent (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, actor_identity TEXT NOT NULL, capability TEXT NOT NULL, target_server_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, token_issuer TEXT NOT NULL, audience TEXT NOT NULL, kid TEXT NOT NULL, issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, installation_id TEXT NOT NULL, installation_generation INTEGER NOT NULL, installation_enrollment_id INTEGER NOT NULL, local_cert_issuer TEXT NOT NULL, local_cert_serial_norm TEXT NOT NULL, local_cert_fingerprint TEXT NOT NULL, target_enrollment_id INTEGER NOT NULL, target_mgmt_issuer TEXT NOT NULL, target_mgmt_serial_norm TEXT NOT NULL, target_mgmt_fingerprint TEXT NOT NULL, revocation_generation INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_management_action_outcome (correlation_id TEXT PRIMARY KEY, team_id INTEGER NOT NULL, result TEXT NOT NULL, result_class TEXT NOT NULL, status_code INTEGER, response_sha256 TEXT, completed_at TEXT NOT NULL DEFAULT '', FOREIGN KEY(correlation_id) REFERENCES kb_management_action_intent(correlation_id));
-- P5-D2a shape-only compatibility.  SQLite exposes no read-token authority,
-- retained bearer, RLS, WORM key-use, or management-read admission path.
CREATE TABLE IF NOT EXISTS kb_management_read_intent (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, team_id INTEGER NOT NULL, actor_identity TEXT NOT NULL, selector TEXT NOT NULL CHECK(selector IN ('agents','config')), capability TEXT NOT NULL, external_method TEXT NOT NULL, external_path TEXT NOT NULL, challenge_nonce BLOB NOT NULL, target_server_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, token_version INTEGER NOT NULL, token_issuer TEXT NOT NULL, audience TEXT NOT NULL, kid TEXT NOT NULL, key_generation INTEGER NOT NULL, publication_generation INTEGER NOT NULL, issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, issuance_deadline TEXT NOT NULL, installation_id TEXT NOT NULL, installation_generation INTEGER NOT NULL, installation_enrollment_id INTEGER NOT NULL, local_cert_issuer TEXT NOT NULL, local_cert_serial_norm TEXT NOT NULL, local_cert_fingerprint TEXT NOT NULL, target_enrollment_id INTEGER NOT NULL, target_mgmt_issuer TEXT NOT NULL, target_mgmt_serial_norm TEXT NOT NULL, target_mgmt_fingerprint TEXT NOT NULL, revocation_generation INTEGER NOT NULL, state TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, jwt TEXT, jwt_sha256 BLOB, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', UNIQUE(correlation_id,jti), UNIQUE(correlation_id,jti,kind), CHECK(external_path='/v1/servers/'||target_server_id||'/'||selector), FOREIGN KEY(correlation_id,jti,kind) REFERENCES kb_management_token_intent_namespace(correlation_id,jti,kind));
CREATE TABLE IF NOT EXISTS kb_management_read_key_use (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, actor_identity TEXT NOT NULL, target_server_id TEXT NOT NULL, selector TEXT NOT NULL CHECK(selector IN ('agents','config')), request_sha256 TEXT NOT NULL, kid TEXT NOT NULL, key_generation INTEGER NOT NULL, publication_generation INTEGER NOT NULL, jwt_sha256 BLOB NOT NULL, result_status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '', FOREIGN KEY(correlation_id,jti) REFERENCES kb_management_read_intent(correlation_id,jti));
-- Per-user remote_writes shape-only compatibility (proposal
-- per-user-remote-writes-authz.md §4).  SQLite exposes no identity intent
-- writer, no authority admission, no RLS and no signing path: the data-plane
-- identity mint requires PostgreSQL.  These exist so a shim-backed developer
-- build has the same table inventory, not so the flow works.
CREATE TABLE IF NOT EXISTS kb_management_identity_intent (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, token_jti TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, subject TEXT NOT NULL, auth_mode TEXT NOT NULL CHECK(auth_mode IN ('oidc','pam')), target_server_id TEXT NOT NULL, token_issuer TEXT NOT NULL, audience TEXT NOT NULL, kid TEXT NOT NULL, issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, installation_id TEXT NOT NULL, installation_generation INTEGER NOT NULL, installation_enrollment_id INTEGER NOT NULL, target_enrollment_id INTEGER NOT NULL, revocation_generation INTEGER NOT NULL, state TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, jwt TEXT, jwt_sha256 BLOB, created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '', UNIQUE(correlation_id,jti), UNIQUE(correlation_id,jti,kind), FOREIGN KEY(correlation_id,jti,kind) REFERENCES kb_management_token_intent_namespace(correlation_id,jti,kind));
CREATE TABLE IF NOT EXISTS kb_management_identity_key_use_intent (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, token_jti TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, subject TEXT NOT NULL, tier TEXT NOT NULL CHECK(tier IN ('off','data','full')), audience TEXT NOT NULL, kid TEXT NOT NULL, token_custody_key_id TEXT NOT NULL, token_version INTEGER NOT NULL, publication_generation INTEGER NOT NULL, publication_candidate_id TEXT NOT NULL, publication_manifest_sha256 BLOB NOT NULL, publication_envelope_sha256 BLOB NOT NULL, vault_seal_epoch INTEGER NOT NULL, hwm_attestation_digest BLOB NOT NULL, purpose TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '');
-- P5-C2d shape-only compatibility.  SQLite exposes no token-authority facade,
-- locking, role split, WORM admission, vault opening, or signing path.
CREATE TABLE IF NOT EXISTS kb_management_token_key_use_intent (correlation_id TEXT PRIMARY KEY, jti TEXT NOT NULL UNIQUE, team_id INTEGER NOT NULL, actor_identity TEXT NOT NULL, target_server_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, kid TEXT NOT NULL, token_custody_key_id TEXT NOT NULL, token_version INTEGER NOT NULL, publication_generation INTEGER NOT NULL, publication_candidate_id TEXT NOT NULL, publication_manifest_sha256 BLOB NOT NULL, publication_envelope_sha256 BLOB NOT NULL, vault_seal_epoch INTEGER NOT NULL, hwm_attestation_digest BLOB NOT NULL, purpose TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS org_egress_binding (
  team_id INTEGER NOT NULL,
  model_id TEXT NOT NULL,
  billable_model TEXT NOT NULL,
  pricing_version INTEGER NOT NULL,
  key_id TEXT NOT NULL,
  vault_principal TEXT NOT NULL,
  vault_agent TEXT NOT NULL DEFAULT '',
  vault_cred TEXT NOT NULL DEFAULT '',
  max_input_tokens INTEGER NOT NULL,
  max_output_tokens INTEGER NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  overage_fenced INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(team_id,model_id)
);
CREATE TABLE IF NOT EXISTS org_egress_dispatch (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  authority_id TEXT NOT NULL,
  request_id TEXT NOT NULL,
  origin_identity TEXT NOT NULL,
  origin_fingerprint TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  team_id INTEGER NOT NULL,
  project_id INTEGER,
  model_id TEXT NOT NULL,
  billable_model TEXT NOT NULL,
  pricing_version INTEGER NOT NULL,
  reserved_max_usd NUMERIC NOT NULL,
  key_id TEXT NOT NULL,
  vault_principal TEXT NOT NULL,
  vault_agent TEXT NOT NULL DEFAULT '',
  vault_cred TEXT NOT NULL DEFAULT '',
  max_input_tokens INTEGER NOT NULL,
  max_output_tokens INTEGER NOT NULL,
  state TEXT NOT NULL,
  owner_token TEXT NOT NULL DEFAULT '',
  owner_generation INTEGER NOT NULL DEFAULT 0,
  owner_instance TEXT NOT NULL DEFAULT '',
  lease_expires_at TEXT,
  http_status INTEGER NOT NULL DEFAULT 0,
  prompt_tokens INTEGER NOT NULL DEFAULT 0,
  completion_tokens INTEGER NOT NULL DEFAULT 0,
  cache_read_tokens INTEGER NOT NULL DEFAULT 0,
  cache_write_tokens INTEGER NOT NULL DEFAULT 0,
  raw_prompt_tokens TEXT NOT NULL DEFAULT '0',
  raw_completion_tokens TEXT NOT NULL DEFAULT '0',
  raw_cache_read_tokens TEXT NOT NULL DEFAULT '0',
  raw_cache_write_tokens TEXT NOT NULL DEFAULT '0',
  realized_usd NUMERIC,
  overage_usd NUMERIC NOT NULL DEFAULT 0,
  liability_overflow INTEGER NOT NULL DEFAULT 0,
  outcome_class TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT '',
  UNIQUE(authority_id,request_id)
);
CREATE INDEX IF NOT EXISTS idx_org_egress_recover
  ON org_egress_dispatch(state,lease_expires_at,id);
